(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ht"] = {"ui":{"skip":"Ale nan kontni a","back":"← Tounen sou AI-gile","lang.button":"Lang: {name}","lang.dialog":"Chwazi yon lang","lang.search":"Chèche lang","lang.none":"Pa gen lang ki koresponn","lang.notYet":"{name} poko tradui","theme.aria":"Chanje tèm: klè, fènwa oswa nwa","theme.toLight":"Pase sou tèm klè","theme.toDark":"Pase sou tèm fènwa","theme.toBlack":"Pase sou tèm nwa (nwa toutbon, dous pou ekran OLED)","words.underline":"Souliye mo sa yo sou paj la","words.underlineHelp":"Pase sourit la sou yon mo ki gen pwen anba l, oswa tape l, pou w wè sa l vle di.","words.col.todo":"Kat yo chwazi pou kounye a: ekip la ap kòmanse ak yo yo apre.","words.col.doing":"Yon AI ap travay sou kat sa a kounye a.","words.col.review":"Yon AI fini travay la; yon lòt verifye l anvan li rive jwenn ou.","words.col.verify":"Ap tann ou: eseye l epi di si l mache.","words.col.team":"Nòt oswa repons ou yo, k ap tann ekip la pran yo.","words.col.done":"Fini epi aksepte.","index.title":"AI-gile: ekip devlopman AI ou a, sou yon sèl tablo","index.description":"AI-gile se yon tablo kanban pou ekip AI ki kode. Yo travay pandan w ap dòmi; ou jwenn yon ti pil kout ak bagay pou ou deside, teste ak aksepte.","hero.logoAlt":"Ikòn tablo AI-gile","hero.h1.html":"Ekip devlopman AI ou a, sou yon sèl&nbsp;tablo.","hero.alpha":"🐣 Pre-alfa fèmen","hero.alphaTitle":"Li bonè e li poko fini: mèsi paske w ap eseye li!","hero.lede":"Yo bati pandan w ap dòmi. Ou reveye sou yon ti pil kout: kèk kesyon, kèk bagay pou teste, yon dyaman koulè wouj violèt oswa de. Klike, aksepte, retounen bò kafe w la.","dl.windows":"Aplikasyon Windows","dl.browser":"Sèvi ak li nan navigatè w","dl.messenger":"📱 Messenger pou telefòn ou","dl.soon":"Talè konsa","dl.notify":"🔔 Di m lè l ouvè","dl.notifySmall":"Alfa oswa beta","hero.secondary":"Agile, men ekip la pa bezwen kafe stand-up. (Yo fè stand-up kanmenm.)","pitch.h2":"AI-gile an kantite mo ou vle","pitch.lede":"Chwazi yon longè, soti nan yon sèl mo rive 144. Chak longè gen pwòp deskripsyon li, ekri espesyalman pou gwosè sa a. Glise kourseur a oswa sèvi ak flèch yo.","pitch.rangeLabel":"Longè an mo","pitch.dice":"🎲 yon lòt vèsyon","pitch.words.one":"{n} mo","pitch.words.other":"{n} mo","pitch.letters.one":"{n} lèt","pitch.letters.other":"{n} lèt","pitch.chars.one":"{n} karaktè","pitch.chars.other":"{n} karaktè","count.line.html.one":"{n} kat sou tablo a kounye a","count.line.html.other":"{n} kat sou tablo a kounye a","people.humans.html.one":"👥 {n} moun","people.humans.html.other":"👥 {n} moun","people.agents.html.one":"🤖 {n} ajan","people.agents.html.other":"🤖 {n} ajan","people.working.html.one":"⚡ {n} ap travay kounye a","people.working.html.other":"⚡ {n} ap travay kounye a","pre.title":"AI-gile: gen yon bagay k ap bati","pre.description":"Gen yon bagay k ap bati isit la. Yon tablo kote ekip AI bati sa ou mande, epi yo aprann ou pandan y ap travay. Pou kounye a, se yon pre-alfa fèmen ak zanmi.","pre.h1":"Gen yon bagay k ap bati isit la. 🤫","pre.line":"Yon tablo kote ekip AI bati sa ou mande, epi yo aprann ou pandan y ap travay. Pou kounye a, se yon pre-alfa fèmen ak zanmi.","pre.btn":"🔔 Di m lè l ouvè","pre.peek":"Dèyè vit la: vrè tablo a, an dirèk. Chak kat se yon ba ki gen koulè.","pre.peekFake":"Dèyè vit la: men ki jan yon tablo k ap travay sanble.","pre.night":"🌙 Gadyen nwit la an chaj · 😴 moun nan ap repoze","features.aria":"Sa li fè","f.pile.h":"Yon sèl pil pou ou","f.pile.html":"<b>Pou ou</b> gen tout sa k ap tann ou, nan tout pwojè yo: kesyon, bagay pou teste, travay sèlman yon moun ka fè. Lis ou a di ki sa ki vini apre ak konbyen tan sa pran.","f.sleep.h":"Ekip ki travay pandan w ap dòmi","f.sleep.p":"Chak pwojè gen yon chèf ak yon ekip ajan AI. Kite yon kòmantè sou yon kat, ekip la reveye, fè travay la, epi remèt li ba ou ak etap yon moun fatige ka swiv.","f.tester.h":"Yon testè AI tcheke anvan","f.tester.p":"Anvan anyen rive jwenn ou, yon testè swiv etap yo nan yon kopi aplikasyon an epi montre sa l te wè, ak yon foto ekran. Pase sou sa ki pase yo epi aksepte yo ak yon sèl klik.","f.proof.h":"Prèv, pa pwomès","f.proof.p":"Chak remiz montre sa ki chanje: fichye yo, diff la, foto ekran yo. Ou pa bezwen louvri chak aplikasyon pou konnen si li fini.","f.chat.h":"Pale ak chèf ou yo","f.chat.p":"Yon ba sou kote ki sanble ak Discord: yon ikòn pou chak pwojè, dyaman koulè wouj violèt pou sa ki bezwen ou. Voye yon chèf yon lide; li fè kat ak yon plan ladan l, ak yon bouton ✅ Go.","f.tidy.h":"Li ranje tèt li","f.tidy.p":"Kat ki gen rapò fusyone nan yon sèl, tit ki mele korije, epi yon tcheke token kenbe kòd la lejè. Mwens bagay pou w ale vini ant yo, mwens pou w panse.","f.private.h":"Pou ou, sou òdinatè w","f.private.li1":"Tablo a mache sou pwòp machin ou epi li reponn ou sèlman.","f.private.li2":"Mesaj prive ant moun yo chifre de bout an bout.","f.private.li3":"Okenn kont, okenn pisteur, okenn cookie.","f.lang.h":"Nan lang ou","f.lang.p":"Plis pase 120 lang, soti nan Olandè, Galwa ak Japonè rive nan pirat, Yoda ak Klingon, ak yon chanjman rapid pou tounen nan Anglè pou jagon pwofesyonèl la.","f.service.h":"Soti nan yon ide rive nan yon vrè sèvis","f.service.p":"Ou bati yon bagay ak AI moun ap sèvi ak li kounye a? Make l kòm yon sèvis epi tablo a ede w fè l mache byen: verifikasyon uptime, yon paj estati piblik, ensidan ak yon rapò ekri, chanjman ki bezwen yon Ale, sovgad yo tcheke chak jou. Èd montre w chak etap pandan w ap avanse.","msgr.h2":"AI-gile Messenger: ekip ou nan pòch ou","msgr.p1":"Pale ak ekip AI ou san ou pa ouvri tablo a. Chat ak chèf pwojè ou yo ak zanmi ou, epi gade etap tès yon kat e reponn yo, tout sa sou telefòn ou.","msgr.p2":"Pou konekte l, eskane yon kòd QR sou tablo ou. Premye fwa? Yon chat demo byen janti ap fè w vizite.","msgr.when":"Android an premye, apre sa yon vèsyon web pou telefòn ak iPhone.","msgr.who":"Chèf pwojè ou","msgr.b1":"Koreksyon mòd fè nwa a pare. Ou vle etap tès yo?","msgr.b2":"Wi, tanpri!","msgr.b3":"1. Ouvri Paramèt. 2. Chwazi Fè nwa. Èske li sanble byen?","tl.aria":"Liy tan soti nan premye konvèsasyon an rive nan plan an","tl.h2":"Soti nan premye chita pale a rive nan sa k ap vini","tl.lede":"Dat ak lè reyèl, nan pwòp fizo orè ou. Apre jodi a, se plan an, san okenn dat pwomèt.","tl.today":"Jodi a","tl.planned":"planifye","tl.doing":"an kou","tl.cards.one":"{n} kat","tl.cards.other":"{n} kat","join.h2":"Vin patisipe","join.lede":"Se yon nèg dwòl ki gen bab, AuDHD ak kèk batay ak sante mantal li, ansanm ak anpil ajan pasyan, k ap bati AI-gile. Pou kounye a li prive, nan yon alfa fèmen ak zanmi. Ou ta renmen eseye l lè l ouvè?","join.btn":"Make enterè m","join.small":"N ap ekri ou pa imèl, pa gen lòt bagay","footer.tag":"AI-gile. Okenn pisteur, okenn cookie, okenn kafe stand-up.","footer.licence":"Lisans biznis","footer.status":"Eta","footer.privacy":"Sa nou kenbe","footer.thanks":"Apèl gras a ChilledChat","form.sending":"Ap voye…","form.failed":"Sa pa mache: eseye ankò pita.","form.offline":"Pa t ka rive jwenn AI-gile: eseye ankò pita.","form.keep":"Nou sèvi ak sa sèlman pou n reponn ou, apre sa nou efase l. Okenn pisteur, okenn cookie.","form.keepLink":"Sa nou kenbe","interest.title":"AI-gile: di m lè alfa a ouvè","interest.description":"Kite imèl ou pou konnen kilè alfa oswa beta fèmen AI-gile a ouvè.","interest.h1":"🔔 Di m lè l ouvè","interest.lede":"AI-gile nan pre-alfa fèmen. Kite imèl ou epi n ap ekri ou yon sèl fwa, lè gen yon plas pou ou.","interest.email":"Imèl ou","interest.which":"Ki tès?","interest.alpha":"Alfa fèmen: bonè, brit, anpil chanjman","interest.beta":"Beta: pi estab, pita","interest.both":"Nenpòt, sa ki rive anvan","interest.submit":"Mete m sou lis la","interest.thanks":"Mèsi! Ou sou lis la.","licence.title":"AI-gile: lisans biznis","licence.description":"Ou sèvi ak AI-gile nan biznis ou? Mande yon lisans biznis gratis.","licence.h1":"📜 Lisans biznis","licence.lede":"Ou sèvi ak AI-gile nan travay? Di nou ki moun ou ye ak sa w fè. Si l fè kèk bon, lisans lan gratis.","licence.company":"Konpayi","licence.website":"Sitwèb","licence.what":"Sa w fè","licence.how":"Ki jan sa ede mond lan","licence.email":"Imèl","licence.submit":"Aplike","licence.thanks":"Mèsi! N ap reponn ou pa imèl.","status.title":"Eta AI-gile","status.h1":"Eta AI-gile","status.quiet":"Tout bagay kalm","status.intro":"Èske AI-gile ap mache kounye a? Paj sa a verifye sit entènèt la, pataj tablo, apèl yo ak telechajman an chak 5 minit.","status.up":"Ap mache (li reponn nan {ms} ms)","status.slow":"Li pa t reponn dènye verifikasyon an, n ap eseye ankò","status.down":"An pann: li pa t reponn de dènye verifikasyon yo","status.svc.web":"Sit entènèt","status.svc.web.offers":"Sit sa a: sa AI-gile ye, ak fòm enterè a","status.svc.boards":"Pataj tablo","status.svc.boards.offers":"Tablo piblik, mesaj ant zanmi ak envitasyon","status.svc.calls":"Apèl","status.svc.calls.offers":"Vwa, videyo ak pataj ekran nan AI-gile","status.svc.download":"Telechajman","status.svc.download.offers":"Enstalatè Windows la ak lyen envitasyon yo","status.checking":"Ap verifye…","status.offline":"Pa ka rive jwenn sèvis eta a kounye a (n ap eseye ankò)","status.updated":"mete ajou {ago}","status.justNow":"kounye a menm","status.min":"{n} min de sa","status.hours":"{n} è de sa","status.days":"{n} jou de sa","privacy.title":"AI-gile: sa nou kenbe","privacy.h1":"Sa nou kenbe","privacy.lede":"An kout: sèlman sa ou voye ban nou, epi pa pou lontan.","privacy.only":"Sèlman sa ou voye ban nou: sa ou tape nan yon fòm, tankou imèl ou. Anyen lòt sou ou.","privacy.sealed":"Li sele pou sèvè nou an pa ka li l: nan navigatè w anvan li pati (sou yon navigatè ki pi ansyen, menm moman li rive a). Se sèlman pwòp tablo pa nou ki ka louvri l.","privacy.server":"Li efase sou sèvè a depi li rive sou tablo nou an. Tout sa ki toujou la apre 30 jou efase kanmenm.","privacy.board":"Nou kenbe l sou tablo nou an sèlman jiskaske nou reponn ou, apre sa nou efase l la tou.","privacy.none":"Okenn pisteur, okenn cookie, okenn analitik.","privacy.local":"Lang ou ak chwa limyè oswa fènwa ou rete nan pwòp navigatè w. Yo pa janm voye yo ban nou.","privacy.ask":"Ou vle l disparèt pi vit? Reponn imèl nou an epi di nou sa.","live.h2":"Gade l ap bati, an dirèk","live.caption":"Chak kat kache: ou wè fòm travay la, pa mo yo.","live.watching.one":"an dirèk: {n} ap gade","live.watching.other":"an dirèk: {n} ap gade","live.last.now":"Dènye kat la deplase jis kounye a","live.last.min.one":"Dènye kat la deplase {n} minit de sa","live.last.min.other":"Dènye kat la deplase {n} minit de sa","live.last.hour.one":"Dènye kat la deplase {n} è de sa","live.last.hour.other":"Dènye kat la deplase {n} è de sa","live.last.day.one":"Dènye kat la deplase {n} jou de sa","live.last.day.other":"Dènye kat la deplase {n} jou de sa","live.offline":"Tablo an dirèk la ap pran yon ti repo. Tounen talè.","live.cols":"Backlog|Pou fè|Ap fèt|Ekip la ap verifye|Pou ou test|Pou ekip la|Fini"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robo.","Delege."]},{"n":2,"texts":["Kanban robo.","Ajan, òganize.","Lide, bati."]},{"n":3,"texts":["Kanban pou robo.","Lide vin fonksyon.","Kanban ajan gratis."]},{"n":5,"texts":["Yon tablo kanban ajan jere.","Ou ekri kat. Ajan bati.","Gratis, lokal, teste, tikotan fou."]},{"n":8,"texts":["Yon tablo kanban gratis kote ajan AI travay.","Ekri yon lide. Ajan yo bati l. Ou aksepte.","Agile pou yon moun ak anpil robo pasyan."]},{"n":13,"texts":["Yon tablo kanban sou òdinatè w kote ajan AI pran kat yo pou travay.","Ekri yon lide. Yon ekip ajan bati l. Yon testè verifye l anvan.","Gratis, san kont, san pisteur: yon tablo, kèk robo, epi ou se chèf la."]},{"n":21,"texts":["AI-gile se yon tablo kanban pou travay ak ajan AI ki kode. Yo pran kat yo; se ou menm ki teste yo epi aksepte yo.","Chak pwojè gen yon chèf ak yon ekip ajan AI. Kite yon kòmantè sou nenpòt kat epi ekip la mete men nan travay.","Yon tablo tach pèsonèl, gratis, ki mache sou pwòp òdinatè w. Se robo ki travay. Se ou ki di wi."]},{"n":34,"texts":["Ou mete lide sou yon tablo. Yon ekip ajan AI transfòme yo an fonksyon ki mache, teste yo, epi remèt yo ba ou ak etap pou eseye. Anyen pa konte kòm fini toutotan ou pa di sa.","AI-gile se yon tablo kanban fèt lakay Rich te bati ak anpil èd ajan li jere kounye a yo. Li gratis, li mache sou òdinatè w, epi li pataje ak zanmi, li pa vann.","Imajine yon tablo kanban òdinè, ak kolòn ki soti nan Backlog rive nan Fini, sof ke se ajan AI k ap pran kat yo. Yo rapòte pwogrè, yo poze kesyon lè yo bloke, epi yo toujou tann dwèt chita w anlè."]},{"n":55,"texts":["AI-gile se yon tablo kanban kote ekip la fèt ak ajan AI. Chak pwojè gen yon chèf ki planifye travay la ak èdè ki bati l. Lè yon fonksyon pare, yon testè AI eseye l epi pran yon foto ekran, answit li rive nan pil ou a. Aksepte l, oswa kite yon kòmantè epi yo refè l.","Li te kòmanse kòm yon fason pou yon moun swiv anpil sesyon kodaj AI an menm tan, epi li grandi an yon vrè tablo. Li mache sou machin ou, li pa mande okenn kont, epi li pa gen pisteur. Li gratis pou zanmi ak nenpòt moun ki gen kiryozite. Li poko fini tou, kidonk atann w ak kèk kote ki brit ak kèk sipriz.","Men vèsyon onèt la. Ou toujou dwe gen lide yo, epi ou toujou dwe tcheke rezilta yo. Sa AI-gile fè se tout sa ki nan mitan: li kenbe kat yo nan lòd, li reveye bon ajan an lè w kite yon kòmantè, li montre egzakteman sa ki chanje, epi li mete tout sa nan yon sèl pil kout pou ou."]},{"n":89,"texts":["AI-gile se yon tablo kanban gratis ou fè mache sou pwòp òdinatè w. Olye de moun, chak pwojè gen yon ekip ajan AI: yon chèf ki fè lide ou yo tounen kat ak yon plan, ak èdè ki pran kat yo dapre priyorite. Lè yon bagay bati, yon testè AI swiv etap tès yo epi montre w sa l te wè. Answit li rete tann nan yon sèl pil ki rele Pou ou. Ou aksepte l, oswa ou kite yon kòmantè epi ekip la eseye yon lòt fwa. Anyen pa janm rive nan Fini san ou.","Kèk bagay ou pa t ap atann. Yon gadyen mennen kolòn Pou fè a plen pandan w ap dòmi, li chwazi kat ki pa bezwen repons ou. Yon konteur token montre konbyen ajan yo sèvi jodi a ak semèn sa a, epi Mòd San Token di yo sispann depanse. Ou ka voye mesaj bay zanmi, epi mesaj prive yo chifre de bout an bout. Tablo a pale anviwon 120 lang, ansanm ak Olandè, Flamann, pirat ak Klingon. Pa gen anyen ki koute yon santim, epi pèsonn pa eseye vann ou l.","AI-gile se yon ti pwojè pèsonèl, se pa yon konpayi. Rich te vle okipe plizyè pwojè kodaj AI san l pa louvri chak aplikasyon pou tcheke yo, konsa li menm ak ajan yo bati yon tablo pou sa, answit yo sèvi ak tablo sa a pou bati rès tèt li. Li nan pre-alfa fèmen, sa vle di li mache, plis oswa mwens, pou yon ti pwiyen zanmi. Pa gen paj pri, pa gen bilten, epi pa gen plan kwasans. Si sa sanble itil, ou ka mande pou eseye l lè l ouvè yon ti jan plis."]},{"n":144,"texts":["AI-gile se yon tablo kanban pou yon moun ak anpil ajan AI. Li mache sou pwòp òdinatè w epi li totalman gratis. Ou ajoute pwojè, epi chak pwojè jwenn yon chèf ak yon ti ekip. Ou pale ak chèf la, yon ti jan tankou sou Discord, epi ou dekri yon lide; chèf la fè l tounen kat ak yon plan, answit li tann ou peze Go. Ekip la pase sou kat yo dapre priyorite, ak yon liy kòmand senp ki fèt pou modèl lang. Anvan anyen tounen jwenn ou, yon testè AI swiv etap yo nan yon kopi aplikasyon an epi tache yon foto ekran. Travay ki fini rive nan pil ou a ak fichye ki chanje yo ak diff la. Ou aksepte l, oswa ou kite yon kòmantè epi ekip la reveye pou eseye ankò. Se sèlman ou ki ka mete yon kat nan Fini.","Men apeprè ki jan yon jou ak AI-gile ye. Nan aswè ou kite kèk kòmantè: bouton sa a nan move kote, lis sa a dwe klase, èske nou ta ka gen yon mòd fènwa. Ou ale dòmi. Ajan yo li kòmantè yo, fè chanjman yo, teste yo epi remèt yo ba ou. Si Pou fè a vin vid, gadyen an ranpli l ak kat nan backlog ki pa bezwen repons ou. Nan maten gen yon sèl pil kout: de twa kesyon ak kèk bagay pou eseye, chak ak etap yon moun ki gen dòmi ka swiv ak yon foto ekran ki montre l ap mache. Ou klike sou yo, aksepte bon yo epi voye rès la tounen. Yon konteur token montre sa tout bagay sa a te sèvi, epi Mòd San Token la pou semèn kote ou bezwen ekonomize. Answit ou manje maten, bagay ajan yo poko ka ede ou ak li.","Pou kòmanse, sa AI-gile pa ye. Se pa yon startup, li pa pou vann, epi pèsonn pa ranmase done ou yo. Se yon tablo gratis ki mache sou òdinatè w, san kont, san pisteur epi san cookie. Sa li ye: yon sèl kote ranje pou wè tout pwojè kodaj AI ou yo alafwa, ak yon ekip ajan k ap fè kat yo epi ou menm k ap pran desizyon yo. Li fusyone kat ki gen rapò, li korije tit ki mele, epi li veye pou kòd la rete lejè. Li pale anviwon 120 lang, soti nan Olandè ak Flamann rive nan pirat ak Klingon. Zanmi ka voye mesaj bay youn lòt, an prive epi chifre. Se Rich ak anpil ajan pasyan ki bati l, pi fò tan ap sèvi ak li menm. Li nan pre-alfa fèmen, kidonk li brit kèk kote. Si sa sanble amizan, mande l byen epi petèt w ap antre bonè."]}],"quips":{"1":"Yon sèl mo. Ak kouraj. Petèt twòp kouraj.","3":"Twa mo. Deja pi onèt pase pifò paj pwodwi.","8":"Uit mo. Toujou pi kout pase yon stand-up.","21":"Longè yo se pwen istwa, san dout. Natirèlman.","55":"Senkant-senk mo. De kat fini pandan w t ap li sa.","144":"Sa a se pi long lan. Pa gen 233. Ajan yo ale dòmi."}},"timeline":{"first-idea.name":"Premye lide a","first-idea.line":"Premye konvèsasyon an, anvan menm yon sèl liy kòd te egziste.","first-board.name":"Premye tablo","first-board.line":"Yon tablo ki swiv pwòp konstriksyon li: kat, kolòn, trennen epi depoze, pwojè.","team-roles.name":"Ekip ak wòl","team-roles.line":"Pwofil ajan, modèl ekip, espas ak ki moun ki fè kisa.","install.name":"Enstalasyon ak vèsyon","install.line":"Yon zip yon zanmi ka enstale, mizajou otomatik, kanal ak retounen anndan.","usage-saver.name":"Ekonomi itilizasyon","usage-saver.line":"Mezire sa chak egzekisyon koute, kenbe kòd la lejè, ekonomize limit ou.","friends.name":"Zanmi ak pataj","friends.line":"Mesaj prive, yon relè mele, envitasyon, wòl ak pwojè pataje.","languages.name":"Lang","languages.line":"Chak tèks ekran nan yon fichye lang, ak Olandè ak Flamann an premye.","ai-tester.name":"Testè AI","ai-tester.line":"Yon testè tcheke chak remiz anvan epi montre sa l te wè.","website.name":"Sitwèb la","website.line":"aigile.lol, teaser la ak liy tan sa a.","streaming.name":"Chat ak difizyon an dirèk","streaming.line":"Discord, Twitch, OBS, mòd streamer, GIF ak emoji.","no-ai.name":"Edisyon San AI","no-ai.line":"Yon tablo pou moun ki kode san AI, ak tablo piblik.","night-watch.name":"Gadyen lannwit","night-watch.line":"Yon gadyen ak yon Scrum Master kenbe ekip yo sou travay pandan w ap dòmi.","p-more.name":"Tout rès la","p-more.line":"Ti lide ki toujou ap tann tou pa yo.","p-android.name":"Telefòn ak Android","p-android.line":"Rive jwenn tablo ou a nan yon telefòn, answit yon aplikasyon Android natif.","p-release.name":"Alfa ak apre","p-release.line":"Alfa fèmen, sit la an dirèk, answit beta.","p-languages.name":"Plis lang","p-languages.line":"130 lang, ak yon mòd imèsyon pou moun k ap aprann.","p-engines.name":"Plis motè AI","p-engines.line":"Chwazi Claude, Codex, Gemini, Copilot oswa Cursor pou chak ajan.","p-pro.name":"Pratik pwofesyonèl","p-pro.line":"Etikèt risk, baryè merge, kat ensidan ak ranpa pwoteksyon.","p-self.name":"Pran swen ou","p-self.line":"Mòd fatige, rapèl pou pran swen tèt ou ak 4:20.","p-servers.name":"Sèvè ak kwasans","p-servers.line":"Paramèt sèvè global, wòl ak planifikasyon pou grandi.","p-livestream.name":"Ekstra difizyon","p-livestream.line":"Chat Twitch, emoji pèsonalize ak yon vi dirèk piblik."},"words":{"button":"📖 Jagon pwofesyonèl","h":"📖 Mo eksplike","intro":"Fòmasyon gratis nan lang senp: chak mo ou rankontre depi premye lide jiska yon sèvis moun konte sou li, ak Agile, bati, kenbe l an sekirite ak travay ak AI sou wout la.","search":"Chèche yon mo…","none":"Pa gen mo ki koresponn.","close":"Fèmen","count":{"one":"{count} mo","other":"{count} mo"},"groups":[{"id":"idea","name":"💡 Lide ak dekouvèt"},{"id":"plan","name":"🗺️ Planifye travay la"},{"id":"agile","name":"🔁 Fason travay Agile"},{"id":"build","name":"🛠️ Bati l"},{"id":"test","name":"🧪 Tès ak kalite"},{"id":"change","name":"🔀 Chanje l san danje"},{"id":"run","name":"🛎️ Fè yon sèvis mache"},{"id":"sec","name":"🔒 Sekirite ak vi prive"},{"id":"ai","name":"🤖 Travay ak AI"},{"id":"money","name":"💰 Lajan ak lisans"}],"list":[{"id":"discovery","g":"idea","word":"Dekouvèt (discovery)","text":"Premye etap la kote w chèche konnen ki pwoblèm ki merite rezoud epi pou ki moun, anvan yo bati anyen.","also":["discovery phase","faz dekouvèt"]},{"id":"problemstmt","g":"idea","word":"Deklarasyon pwoblèm (problem statement)","text":"Yon oswa de fraz ki di ki moun ki gen yon pwoblèm, ki pwoblèm sa a ye ak poukisa li enpòtan, pou tout moun vize menm bagay la.","also":["deklarasyon pwoblèm","problem statements"]},{"id":"user","g":"idea","word":"Itilizatè","text":"Yon moun ki sèvi ak sa ou bati a. Se bezwen li yo ki rezon travay la.","also":["itilizatè","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Pati konsène (stakeholder)","text":"Nenpòt moun ki enterese nan rezilta travay la oswa ki afekte pa li, tankou moun k ap peye pou li, moun k ap sèvi ak li oswa moun k ap sipòte l.","also":["pati konsène","stakeholders"]},{"id":"persona","g":"idea","word":"Pèsona (persona)","text":"Yon moun envante men reyalis ki reprezante yon kalite itilizatè, pou ekip la ka mande: “Èske Sam ta jwenn sa fasil?”","also":["pèsona","personas"]},{"id":"userresearch","g":"idea","word":"Rechèch sou itilizatè (user research)","text":"Pale ak moun reyèl epi gade yo pou konprann sa yo bezwen, olye de devine.","also":["user interviews","entèvyou itilizatè"]},{"id":"journey","g":"idea","word":"Chemen itilizatè (user journey)","text":"Etap yon moun swiv pou rive fè yon bagay, depi premye fwa li tande pale de li jiska lè li fini, menm andeyò pwodwi w la. Lè w trase l, ou wè kote yo bloke.","also":["user journeys","customer journey","vwayaj itilizatè"]},{"id":"painpoint","g":"idea","word":"Pwen doulè (pain point)","text":"Yon bagay ki anbete oswa ki ralanti moun jodi a. Bon pwodwi yo retire pwen doulè yo.","also":["pain points","pwen doulè yo"]},{"id":"assumption","g":"idea","word":"Sipozisyon (assumption)","text":"Yon bagay ou kwè men ou poko verifye. Lè w ekri sipozisyon yo, ou wè kisa pou teste an premye.","also":["sipozisyon","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Ipotèz (hypothesis)","text":"Yon pi bon sipozisyon ou planifye pou verifye, ansanm ak sa ou panse ki pral rive, tankou “moun pral enskri si premye mwa a gratis”.","also":["ipotèz","hypotheses"]},{"id":"experiment","g":"idea","word":"Eksperyans (experiment)","text":"Yon ti tès planifye pou aprann si yon lide mache, anvan w parye anpil sou li.","also":["eksperyans","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Prèv konsèp (proof of concept, PoC)","text":"Yon esè rapid, san fini, pou wè si yon lide ka mache ditou. Anjeneral yo jete l yon fwa yo gen repons lan.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Pwototip (prototype)","text":"Yon premye modèl pwodwi a, souvan imaj ou ka klike sou yo, pou eseye lide a sou moun anvan yo bati l kòrèkteman.","also":["pwototip","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe (esklèt ekran)","text":"Yon senp desen yon ekran ki montre kote bagay yo ale, san koulè ni vrè kontni.","also":["wireframes","esklèt ekran"]},{"id":"mockup","g":"idea","word":"Mockup (modèl vizyèl)","text":"Yon imaj detaye de ki jan yon ekran pral sanble, ak vrè koulè ak tèks, men anyen poko mache.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Dosye biznis (business case)","text":"Rezon pou fè yon pwojè: konbyen li koute, sa li pote oswa sa li fè ekonomize, ak risk yo.","also":["business cases","dosye biznis yo"]},{"id":"feasibility","g":"idea","word":"Fezabilite (feasibility)","text":"Si yon bagay ka vrèman bati epi antreteni avèk tan, lajan ak konpetans ou genyen.","also":["posib pou fè"]},{"id":"outcome","g":"idea","word":"Rezilta (outcome)","text":"Chanjman ou vle pou moun yo, tankou mwens randevou rate. Li pi enpòtan pase kantite bagay ou bati.","also":["outcomes","rezilta yo"],"noTip":1},{"id":"output","g":"idea","word":"Pwodiksyon (output)","text":"Yon bagay ekip la fè, tankou yon nouvo ekran oswa yon rapò. Lefèt ou fè l pa vle di otomatikman li ede yon moun.","also":["outputs","pwodiksyon yo"],"noTip":1},{"id":"successmetric","g":"idea","word":"Mezi siksè (success metric)","text":"Yon nimewo ki di w si travay la te fè sa li te fèt pou li fè, tankou plis moun ki fini kòmand yo.","also":["success metrics","mezi siksè yo"]},{"id":"kpi","g":"idea","word":"Endikatè pèfòmans kle (KPI)","text":"Yon nimewo enpòtan w ap siveye pou wè si bagay yo ap mache byen, tankou kantite enskripsyon chak semèn.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objektif ak rezilta kle (OKR)","text":"Yon fason pou fikse objektif: objektif la di sa w vle, epi kèk rezilta kle se nimewo ki montre w rive la.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Pwodwi (product)","text":"Bagay yo bati epi antreteni pou itilizatè li yo, tankou yon aplikasyon, yon sit wèb oswa yon zouti.","also":["pwodwi","products"],"noTip":1},{"id":"vision","g":"plan","word":"Vizyon pwodwi (product vision)","text":"Yon kout deklarasyon sou ki moun pwodwi a ede ak ki kote li prale alontèm.","also":["vision statement","deklarasyon vizyon"]},{"id":"po","g":"plan","word":"Pwopriyetè pwodwi (product owner, PO)","text":"Moun ki deside sa pou bati ak nan ki lòd, pou ekip la toujou travay sou sa ki pi enpòtan. Nan AI-gile, se ou menm.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Manadjè pwodwi (product manager, PM)","text":"Moun ki pran swen direksyon yon pwodwi: ki pwoblèm li rezoud, pou ki moun ak poukisa. PM ka vle di manadjè pwojè tou, kidonk verifye.","also":["product managers","manadjè pwodwi"]},{"id":"projmgr","g":"plan","word":"Manadjè pwojè (project manager)","text":"Moun ki fè pwojè a rete nan tan ak nan bidjè, ki swiv ki moun ki fè kisa ak pou ki lè.","also":["project managers","manadjè pwojè yo"]},{"id":"roadmap","g":"plan","word":"Fèy wout (roadmap)","text":"Yon plan apwoksimatif sou sa ki ap vini pandan pwochen mwa yo, nan lòd. Li montre direksyon an, pa dat egzak, epi li chanje pandan w ap aprann.","also":["roadmaps","fèy wout yo"]},{"id":"milestone","g":"plan","word":"Etap enpòtan (milestone)","text":"Yon pwen nan yon pwojè ki merite make, tankou “premye vèsyon an an liy” oswa “100 itilizatè”.","also":["milestones","etap enpòtan yo"]},{"id":"mvp","g":"plan","word":"Pwodwi minimòm ki itil (MVP)","text":"Pi piti vèsyon yon pwodwi ki toujou itil pou moun reyèl, pou ou ka aprann nan men yo bonè.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Egzijans (requirement)","text":"Yon bagay pwodwi fini an dwe fè oswa dwe ye.","also":["requirements","egzijans yo"],"noTip":1},{"id":"scope","g":"plan","word":"Peryimèt travay (scope)","text":"Sa ki enkli nan travay la ak, menm jan enpòtan, sa ki pa enkli.","also":["in scope","out of scope","andedan peryimèt la","andeyò peryimèt la"]},{"id":"scopecreep","g":"plan","word":"Peryimèt k ap gonfle (scope creep)","text":"Lè yo ajoute plis an plis bagay nan travay la piti piti, san pèsonn pa dakò sou tan oswa lajan siplemantè a, kidonk li pa janm fin fini.","also":["feature creep","scope creep","peryimèt k ap gonfle"]},{"id":"feature","g":"plan","word":"Fonksyonalite (feature)","text":"Yon bagay pwodwi a ka fè pou moun, tankou “reyinisyalize modpas ou”.","also":["features","fonksyonalite yo"],"noTip":1},{"id":"epic","g":"plan","word":"Epic (gwo travay)","text":"Yon gwo moso travay, twò gwo pou fèt yon sèl kou, kidonk yo koupe l an ti kat.","also":["epics","gwo travay"]},{"id":"story","g":"plan","word":"Istwa itilizatè (user story)","text":"Yon ti moso travay ekri apati pwen de vi itilizatè a: “Kòm yon achtè, mwen vle sove panye m, pou m ka fini pita.” Li kòmanse yon konvèsasyon sou sa pou bati.","also":["user stories","istwa itilizatè yo"]},{"id":"ac","g":"plan","word":"Kritè akseptasyon (acceptance criteria, AC)","text":"Verifikasyon yon kat dwe pase pou konsidere l fini, dakò anvan travay la kòmanse, tankou “panye a toujou la apre m dekonekte epi rekonekte”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Tach (task)","text":"Yon sèl djòb pou fè, souvan yon ti etap nan yon istwa pi gwo.","also":["tasks","tach yo"],"noTip":1},{"id":"ticket","g":"plan","word":"Tikè (ticket)","text":"Yon lòt non pou yon kat: yon moso travay oswa yon demann, swiv depi kòmansman jiska lafen.","also":["tickets","tikè yo"]},{"id":"priority","g":"plan","word":"Priyorite","text":"Ki jan yon bagay enpòtan oswa ijan konpare ak tout lòt bagay yo, pou travay ki pi enpòtan an fèt an premye.","also":["priyorite yo","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Priyorizasyon","text":"Mete travay nan lòd enpòtans. Yon fason komen se MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimasyon (estimate)","text":"Yon kalkil apeprè sou gwosè yon moso travay oswa konbyen tan li ap pran. Se yon kalkil apeprè, pa yon pwomès.","also":["estimates","estimation","estimasyon yo"],"noTip":1},{"id":"storypoints","g":"plan","word":"Pwen istwa (story points)","text":"Yon fason pou kalkile gwosè travay lè w konpare kat yo youn ak lòt (“apeprè de fwa pi gwo pase sa a”) olye ou konte an èdtan. Yo pa fèt pou konpare ekip yo.","also":["story point"]},{"id":"tshirt","g":"plan","word":"Gwosè T-shirt (T-shirt sizing)","text":"Devine gwosè travay la kòm S, M, L oswa XL. Rapid epi ase bon pou planifikasyon bonè.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker (poker planifikasyon)","text":"Yon jwèt pou estime: tout moun montre yon kat gwosè an menm tan, epi moun ki chwazi pi wo a ak moun ki chwazi pi ba a eksplike poukisa.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Depandans (dependency)","text":"Lè yon moso travay pa ka kòmanse oswa fini jiskaske yon lòt fini.","also":["dependencies","depandans yo"]},{"id":"blocker","g":"plan","word":"Blokaj (blocker)","text":"Nenpòt bagay ki anpeche travay la avanse kounye a, tankou yon repons ki manke oswa yon zouti kase.","also":["blockers","blokaj yo"]},{"id":"deadline","g":"plan","word":"Dat limit (deadline)","text":"Dat yon bagay dwe fini.","also":["deadlines","dat limit yo"],"noTip":1},{"id":"deliverable","g":"plan","word":"Livrab (deliverable)","text":"Yon bagay konkrè travay la pwodui epi lonje ba moun, tankou yon paj ki mache oswa yon rapò.","also":["deliverables","livrab yo"]},{"id":"forecast","g":"plan","word":"Previzyon (forecast)","text":"Yon prediksyon sou sa ki gen chans rive, tankou ki lè travay la ap fini, selon sa ou konnen jiskaprezan.","also":["forecasts","previzyon yo"],"noTip":1},{"id":"metric","g":"plan","word":"Mezi (metric)","text":"Nenpòt bagay ou mezire epi swiv avèk tan, tankou vizit sou paj yo oswa konbyen tan yon reparasyon pran.","also":["metrics","mezi yo"]},{"id":"feedback","g":"plan","word":"Feedback (opinyon moun)","text":"Sa moun di w sou travay ou, bon kou move. Jwenn li bonè epi souvan se kè Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Lis datant lide ak travay yo poko planifye, ak sa ki pi enpòtan an anlè. Anyen la a pa travay jiskaske li pase nan Pou fè."},{"id":"sprint","g":"agile","word":"Sprint","text":"Yon peryòd travay kout ak fiks (souvan yon semèn oswa de, pa janm plis pase yon mwa) ak yon objektif ak yon kantite kat dakò pou fini.","also":["sprints"]},{"id":"standup","g":"agile","word":"Reyinyon kout","text":"Yon kout pwen chak jou: sa chak manm ekip la te fè, sa yo pral fè answit ak sa k ap bloke yo. Nan Scrum yo rele l daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","reyinyon chak jou"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Yon fason pou travay kote kat yo deplase nan kolòn yon tablo (tankou Pou fè, Ap fèt, Fini) epi ekip la limite konbyen ki an kou alafwa, pou travay la kontinye koule."},{"id":"wip","g":"agile","word":"Limit WIP","text":"WIP se kout pou work in progress (travay an kou). Yon limit WIP se pi gwo kantite kat yon kolòn ta dwe gen alafwa, pou ekip la fini bagay anvan li kòmanse plis.","also":["WIP","WIP limit"]},{"id":"dod","g":"agile","word":"Definisyon Fini","text":"Ti lis ekip la sou sa “fini” vle di, tankou teste ak eksplike, anvan yo ba ou yon kat. Marasa l, Definisyon Pare, di ki lè yon kat klè ase pou kòmanse.","also":["Definition of Ready","DoD","DoR","definisyon fini"]},{"id":"retro","g":"agile","word":"Retro","text":"Yon gade regilye dèyè sou jan ekip la travay, pou dakò sou youn oswa de bagay pou fè pi byen pwochen fwa. Kout pou retrospective. Nan AI-gile, yon retro pwopoze yon chanjman nan fason ekip la travay, epi ou di Go oswa Poko.","also":["retros","retrospektiv","retrospective"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Tout moun sou pon an: anpil moun kite lòt travay pou ranje yon sèl bagay ijan ansanm jiskaske li rezoud. Nan AI-gile, tout ekip yo ede sou yon sèl pwojè, epi lòt pwojè yo tann pandan sa.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Nan Scrum, moun ki ede ekip la travay byen: retire sa k ap bloke yo, kenbe reyinyon yo sou bon wout epi antrene bon abitid, san kòmande pèsonn. Nan AI-gile, Chèf Scrum Master la repere kat ki bloke, pouse ekip yo epi raple w sa k ap tann, nan tout pwojè yo.","also":["Chèf Scrum Master","Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Yon fason pou travay ak ti etap: bati yon ti kras, montre vrè rezilta souvan, aprann nan sa moun di epi chanje plan an pandan w ap avanse, olye de planifye tout bagay davans.","also":["Agile development","agile ways of working","travay Agile"]},{"id":"manifesto","g":"agile","word":"Manifès Agile (Agile Manifesto)","text":"Yon kout deklarasyon moun ki fè lojisyèl te ekri an 2001. Li mete moun, rezilta ki mache, travay kole kole ak kliyan yo ak reyaji devan chanjman pi devan gwo plan ak anpil papye.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall (kaskad)","text":"Ansyen fason pou travay: planifye tout bagay, answit bati tout bagay, answit teste tout bagay, yon etap apre yon lòt. Chanjman ki vini ta yo difisil epi chè.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iterasyon (iteration)","text":"Yon tou kote ou bati yon bagay, verifye l epi amelyore l. Travay Agile se yon seri tou konsa youn dèyè lòt, epi yon sprint se yon kalite tou.","also":["iterations","iterasyon yo"]},{"id":"increment","g":"agile","word":"Enkreman (increment)","text":"Yon nouvo moso k ap mache ki ajoute nan pwodwi a pandan yon sprint oswa yon tou travay, epi ki kole ak sa ki te la deja.","also":["increments","enkreman"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Yon fason Agile ki popilè pou travay: yon ti ekip travay nan kout sprint pou rive nan yon objektif, ak wòl ki fiks epi kèk reyinyon regilye pou planifye, verifye ak amelyore."},{"id":"scrumteam","g":"agile","word":"Ekip Scrum","text":"Ti gwoup ki fè travay la nan Scrum: yon pwopriyetè pwodwi, yon Scrum Master ak devlopè yo.","also":["Scrum teams","ekip Scrum yo"]},{"id":"ceremonies","g":"agile","word":"Evènman Scrum","text":"Reyinyon regilye nan Scrum: planifikasyon sprint, scrum chak jou, revizyon sprint la ak retro a. Anpil moun rele yo seremoni.","also":["ceremonies","Scrum ceremonies","seremoni"]},{"id":"sprintplan","g":"agile","word":"Planifikasyon sprint","text":"Reyinyon nan kòmansman yon sprint kote ekip la dakò sou poukisa sprint lan enpòtan, ki kat pou pran ak ki jan pou kòmanse.","also":["planning meeting","reyinyon planifikasyon"]},{"id":"sprintgoal","g":"agile","word":"Objektif sprint","text":"Yon fraz ki di pou kisa yon sprint fèt. Ti tach yo ka chanje sou wout la, toutotan objektif la atenn.","also":["sprint goals","objektif sprint yo"]},{"id":"sprintbacklog","g":"agile","word":"Backlog sprint (sprint backlog)","text":"Kat yo chwazi pou sprint kounye a, ak plan ekip la pou fè yo.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Backlog pwodwi (product backlog)","text":"Lis konplè, an lòd, tout bagay yo ta ka bati pou pwodwi a, sa ki pi enpòtan an anlè. Li toujou ap chanje pandan w ap aprann.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Objektif pwodwi","text":"Pi gwo rezilta pwodwi a ap travay pou li, ki ede ekip la chwazi sa pou fè answit.","also":["product goals","objektif pwodwi yo"]},{"id":"refinement","g":"agile","word":"Rafinaj backlog (backlog refinement)","text":"Pase nan backlog la regilyèman pou netwaye, divize, mete nan lòd epi ajoute detay nan kat yo, pou yo pare pou pran. Yo rele l backlog grooming tou.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Revizyon sprint","text":"Yon reyinyon nan fen yon sprint kote ekip la montre sa li fini epi tande sa moun panse, pou deside sa k ap vini answit.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo (demonstrasyon)","text":"Montre travay ki fini an k ap mache, an dirèk, bay moun ki te mande l yo.","also":["demos","demonstrasyon"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox (bwat tan)","text":"Yon kantite tan fiks pou yon bagay. Lè li fini, ou kanpe, menm si pa tout bagay fini.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Vitès (velocity)","text":"Konbyen travay yon ekip anjeneral fini nan yon sprint, yo itilize l pou planifye konbyen pou pran pwochen fwa. Se pa yon nòt pou jan moun travay di.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Kapasite (capacity)","text":"Konbyen travay ekip la ka pran nan yon peryòd, apre vakans ak lòt djòb yo.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart (graf dekwasans)","text":"Yon graf travay ki rete nan yon sprint k ap desann jou apre jou. Si liy lan rete plat, gen yon bagay ki bloke.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart (graf kwasans)","text":"Yon graf travay ki fini k ap monte avèk tan, bò kote total ki te planifye a, pou w wè ki lè w ap rive.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Tablo Kanban","text":"Tablo a li menm: yon kolòn pou chak etap travay la, ak kat k ap deplase de yon kolòn nan yon lòt.","also":["Kanban boards","tablo Kanban yo"]},{"id":"pullsys","g":"agile","word":"Sistèm rale (pull system)","text":"Yon fason pou travay kote nouvo travay kòmanse sèlman lè yon moun gen plas pou pran l, olye de pouse l sou yon moun ki gen men plen.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Koule (flow)","text":"Ki jan travay la deplase byen sou tablo a. Bon koule vle di kat yo kontinye avanse olye yo anpile.","also":["flow of work","koule travay"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time (tan total)","text":"Konbyen tan sa pran depi yon moun mande yon bagay jiskaske li fini.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time (tan travay)","text":"Konbyen tan yon kat pran depi travay la kòmanse vre sou li jiska lè li fini.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput (kantite fini)","text":"Konbyen kat ki fini nan yon semèn, oswa nan nenpòt peryòd fiks.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck (kou boutèy)","text":"Etap kote travay la anpile epi ralanti tout sa ki dèyè l, tankou kou etwat yon boutèy.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane (koulwa)","text":"Yon ranje sou tablo a ki gwoupe kat yon sèl kalite, tankou travay ijan oswa kat yon ekip.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Yon fason pou travay ki koupe gaspiyaj (tout sa ki pa ede kliyan an) epi ki kenbe travay la ap koule."},{"id":"waste","g":"agile","word":"Gaspiyaj (waste)","text":"Nan Lean, tout sa ki mande efò men ki pa ede kliyan an, tankou tann, refè travay oswa bati bagay pèsonn pa itilize.","noTip":1},{"id":"kaizen","g":"agile","word":"Amelyorasyon kontinyèl (kaizen)","text":"Vin yon ti jan pi bon tout tan gras ak ti chanjman regilye, answit verifye si yo te ede. Retro se yon fason pou fè l. Yo rele l kaizen tou.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Ekip ki òganize tèt li (self-organising team)","text":"Yon ekip ki deside pou kont li ki jan pou fè travay la, olye yo di l etap pa etap.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Ekip miltifonksyonèl (cross-functional team)","text":"Yon ekip ki gen tout konpetans li bezwen pou fini travay la pou kont li, tankou konsepsyon, konstriksyon ak tès.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike (ti rechèch)","text":"Yon kout rechèch ki gen limit tan pou reponn yon kesyon anvan w angaje w nan vrè travay la.","also":["spikes"]},{"id":"rework","g":"agile","word":"Refè travay (rework)","text":"Fè travay la ankò paske li pa t bon premye fwa a.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Fason pou sèvi ak Agile atravè anpil ekip nan yon gwo òganizasyon. SAFe (Scaled Agile Framework) se yon egzanp byen konnen.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Katab pwojè a ki gen kòd la ak tout istwa commits li. Li ka rete sou òdinatè w, sou GitHub, oswa tou de.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Yon liy travay apa nan kòd la, pou ka fè chanjman san manyen vèsyon prensipal la.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Yon foto sove nan kòd la, ak yon ti nòt sou sa ki chanje. Ou ka toujou tounen nan youn.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Voye foto ou sove yo (commits) soti sou òdinatè sa a nan kopi pataje sou entènèt la, tankou GitHub, pou yo gen sovgad epi lòt moun ka rale yo."},{"id":"merge","g":"build","word":"Merge","text":"Rantre chanjman yon branch nan yon lòt, anjeneral retounen nan vèsyon prensipal la."},{"id":"pr","g":"build","word":"Pull request","text":"Mande pou chanjman yon branch verifye epi rantre nan vèsyon prensipal la. Gen sit ki rele l merge request.","also":["PR","PRs","merge request","demann fizyon"]},{"id":"refactor","g":"build","word":"Refactor","text":"Ranje kòd la san chanje sa li fè: fichye pi piti, non pi klè, mwens repetisyon."},{"id":"bug","g":"build","word":"Bug","text":"Yon bagay ki pa mache jan li ta dwe.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revizyon pa yon kolèg","text":"Yon dezyèm pè je: yon moun ki pa otè a verifye travay la anvan l rive jwenn ou, pou mwens erè pase. Nan AI-gile, yon lòt AI verifye chak kat.","also":["peer review","code review"]},{"id":"code","g":"build","word":"Kòd (code)","text":"Enstriksyon ekri ki di yon òdinatè sa pou l fè. Yo rele l kòd sous tou.","also":["source code","kòd sous"],"noTip":1},{"id":"proglang","g":"build","word":"Lang pwogramasyon (programming language)","text":"Yon lang pou ekri kòd, tankou JavaScript, Python oswa Java. Chak lang bon pou diferan travay.","also":["programming languages","lang pwogramasyon yo"]},{"id":"developer","g":"build","word":"Devlopè (developer, dev)","text":"Yon moun ki ekri epi chanje kòd. Yo rele l pwogramè oswa enjenyè lojisyèl tou.","also":["developer","developers","programmer","programmers","software engineer","pwogramè"]},{"id":"software","g":"build","word":"Lojisyèl (software)","text":"Pwogram ki mache sou òdinatè ak telefòn, kontrèman ak machin yo menm (materyèl la, hardware).","noTip":1},{"id":"app","g":"build","word":"Aplikasyon (app)","text":"Kout pou aplikasyon: yon pwogram moun sèvi ak li pou fè yon bagay, sou yon telefòn, yon òdinatè oswa nan yon navigatè wèb.","also":["apps","application","applications","aplikasyon yo"],"noTip":1},{"id":"webapp","g":"build","word":"Aplikasyon wèb (web app)","text":"Yon aplikasyon ki mache nan yon navigatè wèb, kidonk pa gen anyen pou enstale.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end (pati ou wè)","text":"Pati nan yon aplikasyon ou wè epi ou klike sou li: ekran yo, bouton yo ak mo yo, souvan nan navigatè w la.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end (pati dèyè)","text":"Pati dèyè rido nan yon aplikasyon ki kenbe done yo epi ki fè travay la lè w klike sou yon bagay, tankou verifye modpas ou.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack (tout pati yo)","text":"Travay sou pati devan an ak pati dèyè a tou de.","also":["full-stack"]},{"id":"ui","g":"build","word":"Entèfas itilizatè (UI)","text":"Sa yon moun wè epi itilize sou ekran: aranjman an, bouton yo, meni yo ak tèks la.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Eksperyans itilizatè (UX)","text":"Ki jan sa ye pou sèvi ak yon bagay: fasil, klè e agreyab, oswa konfizyon e lan.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Aksesibilite (a11y)","text":"Fè bagay yo itilizab pa tout moun, ansanm ak moun ki pa wè byen, ki pa ka sèvi ak sourit oswa ki itilize yon lektè ekran.","also":["a11y"]},{"id":"responsive","g":"build","word":"Konsepsyon adaptatif (responsive design)","text":"Fè paj yo adapte epi mache byen sou nenpòt gwosè ekran, depi yon telefòn rive nan yon gwo monitè."},{"id":"designsys","g":"build","word":"Sistèm konsepsyon (design system)","text":"Yon twous komen koulè, polis, bouton ak règ, pou chak ekran sanble epi konpòte l menm jan.","also":["design systems"]},{"id":"architecture","g":"build","word":"Achitekti (architecture)","text":"Fòm jeneral yon sistèm: ki pati prensipal yo ye epi ki jan yo pale youn ak lòt."},{"id":"database","g":"build","word":"Baz done (database, DB)","text":"Yon depo enfòmasyon òganize, tankou yon fèy kalkil trè pwisan aplikasyon an ka li epi chanje.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Chema baz done (schema)","text":"Aranjman yon baz done: ki tab enfòmasyon li genyen ak sa ki antre nan chak.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Kout pou structured query language: lang yo itilize pou mande anpil baz done enfòmasyon oswa pou chanje yo.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Done (data)","text":"Enfòmasyon yon òdinatè kenbe, tankou non, kòmand oswa paramèt.","also":["dataset","datasets","data"],"noTip":1},{"id":"server","g":"build","word":"Sèvè (server)","text":"Yon òdinatè ki toujou limen epi ki reponn demann lòt òdinatè yo, tankou voye yon paj wèb lè w vizite l.","also":["servers","sèvè yo"]},{"id":"client","g":"build","word":"Kliyan (client)","text":"Bò ki mande yon bagay, anjeneral navigatè w oswa aplikasyon w, k ap pale ak yon sèvè. Nan biznis, li vle di yon achtè tou.","also":["clients","kliyan yo"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Kout pou application programming interface: yon meni demann yon pwogram ka fè bay yon lòt, tankou mande yon sèvis metewolojik previzyon jodi a.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint (pwen aksè)","text":"Yon atik sou meni yon API: yon adrès wèb yon pwogram ka rele pou jwenn oswa voye yon bagay.","also":["endpoints"]},{"id":"integration","g":"build","word":"Entegrasyon (integration)","text":"Konekte de sistèm pou yo travay ansanm, tankou boutik ou ki voye kòmand yo nan lojisyèl kontabilite w.","also":["integrations","entegrasyon yo"]},{"id":"webhook","g":"build","word":"Webhook","text":"Yon mesaj yon sistèm voye bay yon lòt poukont li nan moman yon bagay rive, tankou “peman resevwa”.","also":["webhooks"]},{"id":"library","g":"build","word":"Bibliyotèk (library)","text":"Kòd pare yon lòt moun te ekri, ke ou ka reitilize olye ou ekri l ou menm.","also":["libraries","bibliyotèk yo"],"noTip":1},{"id":"framework","g":"build","word":"Framework (kad travay)","text":"Yon estrikti pare pou bati yon aplikasyon ki deside anpil bagay sou ki jan yo òganize kòd la, tankou yon eskèlèt kay ou ranpli.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Twous devlopman lojisyèl (SDK)","text":"Yon bwat zouti, kòd ak egzanp pou bati lojisyèl pou yon sèl platfòm oswa sèvis.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Depandans lojisyèl (software dependency)","text":"Yon bibliyotèk oswa yon zouti kòd ou bezwen pou l mache. Kenbe yo ajou enpòtan pou sekirite.","also":["software dependencies"]},{"id":"package","g":"build","word":"Pakè (package)","text":"Yon pakèt kòd pare ou ka enstale epi itilize nan yon pwojè.","also":["packages","pakè yo"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Jestyonè pakè (package manager)","text":"Yon zouti ki telechaje epi mete ajou pakè kòd ou bezwen yo. npm se youn ki komen.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Zouti ki pi itilize pou kenbe istwa chanjman kòd, an fòm commits ak branches."},{"id":"github","g":"build","word":"GitHub","text":"Yon sit wèb ki kenbe repo Git yo sou entènèt, pou ekip yo ka pataje kòd, revize chanjman epi swiv travay la."},{"id":"vcs","g":"build","word":"Kontwòl vèsyon (version control)","text":"Kenbe tout istwa chak chanjman nan fichye yo, pou w ka wè ki moun ki chanje kisa epi retounen si sa nesesè. Git fè sa.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone (kopi konplè)","text":"Fè pwòp kopi konplè w yon repo, ak istwa li, sou òdinatè w.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (rale)","text":"Rale dènye commits yo soti nan kopi pataje a (tankou GitHub) sou òdinatè w. Kontrè push la.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branch prensipal (main branch)","text":"Vèsyon ofisyèl kòd la tout moun travay apati li, souvan rele main oswa master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Konfli fizyon (merge conflict)","text":"Lè de chanjman manyen menm liy yo yon fason diferan, kidonk òdinatè a pa ka mete yo ansanm epi yon moun dwe chwazi.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff (diferans)","text":"Yon vi ki montre egzakteman sa ki chanje ant de vèsyon: liy ki ajoute ak liy ki retire.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork (kopi pèsonèl)","text":"Pwòp kopi w yon repo yon lòt moun, ou ka chanje san afekte pa li.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script (skrip)","text":"Yon ti pwogram ki fè yon sèl djòb poukont li, tankou ranje fichye oswa lanse aplikasyon an.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build (konstriksyon)","text":"Transfòme kòd la an yon bagay ki pare pou mache, oswa rezilta ki pare pou mache a li menm.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Konpile (compile)","text":"Tradui kòd moun ekri an yon fòm òdinatè a ka egzekite dirèkteman.","also":["compiler"]},{"id":"cli","g":"build","word":"Liy kòmand (CLI)","text":"Yon fenèt tèks kote w tape enstriksyon pou òdinatè a olye w klike. Yo rele l tèminal tou.","also":["command line","command-line","CLI","terminal","tèminal"]},{"id":"config","g":"build","word":"Konfigirasyon (config)","text":"Paramèt ki kontwole ki jan lojisyèl la konpòte l, kenbe apa de kòd la pou yo fasil pou chanje.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Varyab anviwònman (environment variable)","text":"Yon paramèt yo bay yon pwogram lè l kòmanse, souvan pou adrès oswa modpas pou yo pa ekri nan kòd la.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging (chèche epi korije erè)","text":"Chèche poukisa yon bagay pa mache, epi korije l.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming (pwogramasyon an pè)","text":"De moun (oswa yon moun ak yon AI) k ap travay ansanm sou menm kòd la, youn ap tape epi lòt la ap verifye.","also":["pairing"]},{"id":"docs","g":"build","word":"Dokimantasyon (docs)","text":"Eksplikasyon ekri sou ki jan yon bagay mache oswa ki jan pou sèvi ak li.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Premye fichye pou li nan yon repo: ki sa pwojè a ye epi ki jan pou fè l mache.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Sistèm eritaj (legacy system)","text":"Yon ansyen sistèm yo toujou sèvi ak li ki difisil pou chanje, souvan paske ti kras moun toujou konprann li.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Dèt teknik (technical debt)","text":"Rakousi ki fè w ekonomize tan kounye a men ki ralanti chanjman pita, tankou yon prè ki ajoute enterè. Refactoring peye l.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Yon verifikasyon pou wè si yon bagay mache jan li dwe. Gen kèk tès òdinatè a fè poukont li chak fwa kòd la chanje; lòt yo se ou menm k ap eseye yon kat ki fini anvan ou aksepte l.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kout pou quality assurance: tout sa yo fè pou asire travay la bon anvan l ale an liy. Nan AI-gile sa vle di verifikasyon otomatik yo: lè QA wouj, yon bagay echwe, epi li pa ka ale an liy jiskaske sa korije.","also":["verifikasyon kalite","quality checks"]},{"id":"testpile","g":"test","word":"Pil tès","text":"Kat ki fini k ap tann ou eseye yo, youn apre lòt. Aksepte youn oswa voye l tounen ak yon nòt, epi pwochen an parèt.","also":["test pile"]},{"id":"autotest","g":"test","word":"Tès otomatik (automated test)","text":"Yon verifikasyon òdinatè a fè poukont li chak fwa kòd la chanje, pou kenbe erè bonè.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Tès manyèl (manual test)","text":"Yon moun ki eseye travay la ak men l pou wè si li konpòte l jan li dwe.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Tès inite (unit test)","text":"Yon ti verifikasyon otomatik sou yon sèl ti moso kòd pou kont li.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Tès entegrasyon (integration test)","text":"Yon verifikasyon ki gade si plizyè pati mache byen ansanm, pa sèlman youn apre lòt.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"Tès bout-an-bout (end-to-end test, E2E)","text":"Yon tès ki aji tankou yon vrè itilizatè depi kòmansman jiska fen, tankou enskri, achte epi peye.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Tès akseptasyon itilizatè (UAT)","text":"Moun ki te mande travay la eseye l yo menm epi di si li fè sa yo bezwen. Pil tès AI-gile a se vèsyon pa li a.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regresyon (regression)","text":"Yon bagay ki te konn mache men ki kase apre yon chanjman. Tès regresyon verifye si ansyen bagay yo toujou mache.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test (tès rapid)","text":"Yon verifikasyon trè rapid si pi gwo bagay yo mache menm, pa egzanp touswit apre yon chanjman mete an liy. Si l echwe, kanpe epi gade.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Tès eksplorasyon (exploratory testing)","text":"Eseye pwodwi a lib epi fouye l nan tout kalite fason, pou jwenn pwoblèm verifikasyon planifye yo ta rate.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Ka tès (test case)","text":"Yon senaryo ekri pou eseye: etap yo ak sa ki ta dwe rive.","also":["test cases"]},{"id":"coverage","g":"test","word":"Kouvèti tès (test coverage)","text":"Ki kantite nan kòd la tès otomatik yo verifye. Anjeneral plis se pi sèten, men yon gwo kouvèti pou kont li pa pwouve kòd la mache byen.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Done tès (test data)","text":"Enfòmasyon egzanp envante yo sèvi pandan tès yo, pou pa ekspoze detay prive okenn moun reyèl.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Ka limit (edge case)","text":"Yon sitiyasyon ki pa abityèl, nan limit yo, tankou yon fòm vid oswa yon non ki gen yon apostwòf, kote bagay yo souvan kase.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Chemen kontan (happy path)","text":"Wout nòmal la kote tout bagay mache byen. Bon tès eseye tou chemen kote bagay yo mal pase."},{"id":"perftest","g":"test","word":"Tès pèfòmans (performance testing)","text":"Verifye ki vitès yon bagay ye ak ki jan li reziste anba presyon.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Tès chaj (load testing)","text":"Verifye ki jan yon sistèm reziste lè anpil moun sèvi ak li alafwa.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Tès sekirite (security testing)","text":"Chèche feblès ki ta kite yon moun mal sèvi ak yon sistèm oswa wè sa li pa ta dwe wè.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Tès aksesibilite (accessibility testing)","text":"Verifye si moun ki gen diferan kapasite ka sèvi ak pwodwi a, ansanm ak yon lektè ekran oswa sèlman yon klavye.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Yon verifikasyon otomatik ki repere erè posib ak move style nan kòd la, tankou yon korektè òtograf pou pwogram.","also":["linter","lint"]},{"id":"static","g":"test","word":"Analiz estatik (static analysis)","text":"Verifye kòd la pou pwoblèm lè w li l otomatikman, san w pa egzekite l.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Tès enstab (flaky test)","text":"Yon tès ki pafwa pase epi pafwa echwe san rezon klè, kidonk ou pa ka fè l konfyans nèt.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Repwodui (repro)","text":"Fè yon bug rive ankò espre lè w swiv menm etap yo, pou ka etidye l epi korije l. Ekri etap sa yo se pati ki pi itil nan yon rapò bug.","also":["repro","reproduce","steps to reproduce","etap pou repwodui"]},{"id":"severity","g":"test","word":"Gravite (severity)","text":"Ki jan efè yon pwoblèm grav, depi yon ti anmèdman jiska lè tout bagay kanpe.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Kopye yon nouvo vèsyon lojisyèl la sou òdinatè ki fè l mache yo, tankou yon kopi tès oswa sèvis an liy lan."},{"id":"release","g":"change","word":"Vèsyon","text":"Yon pake travay fini ki gen yon non, ki ale an liy ansanm, ak ti nòt sou sa ki chanje. 🚀 Vèsyon ekri nòt yo apati kat ki fini yo.","also":["vèsyon yo","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Retounen nan dènye vèsyon ki te mache lè yon nouvo lakòz pwoblèm. Nan AI-gile, Roll back rasanble etap anilasyon ekri sou chak chanjman nan yon sèl lis kontwòl.","also":["roll back","retounen dèyè"]},{"id":"live","g":"change","word":"An liy","text":"Vrè vèsyon moun yo sèvi ak li a, pa yon kopi pou fè esè. Devlopè yo rele l production tou.","also":["live","production","pwodiksyon"],"noTip":1},{"id":"change","g":"change","word":"Chanjman","text":"Yon chanjman planifye sou yon bagay moun konte sou li, ekri davans: ki sa, poukisa, risk la, ki lè, ak ki jan pou defèt li. Kòmanse youn ak 🔀 Leve yon chanjman.","also":["chanjman yo","demann chanjman","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Yon bagay ki ka mal pase, ak yon nòt selon ki chans li genyen pou rive ak ki jan li ta grav. ⚠️ Risk kenbe yo nan yon sèl lis, pi gwo nòt la anvan, chak ak yon dat pou gade l ankò.","also":["risk yo","rejis risk","risk register"]},{"id":"chgwin","g":"change","word":"Fenèt chanjman","text":"Moman lè chanjman ka ale an liy, tankou yon mardi swa trankil. Andeyò yon fenèt, yon kat chanjman pa ka fini, sòf si se yon ijans.","also":["fenèt chanjman yo","change window"]},{"id":"gonogo","g":"change","word":"Ale / Pa ale","text":"Yon dènye verifikasyon jis anvan yon chanjman ale an liy: chak moun ki dwe apwouve di Ale oswa Pa ale. Li ale sèlman si tout moun di Ale.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Apwobasyon","text":"Tann yon wi anvan travay la kòmanse. Yon kat yon zanmi leve, oswa yon chanjman, ap tann nan ✅ Apwobasyon jiskaske ou apwouve l oswa refize l.","also":["apwobasyon yo","approval"]},{"id":"quiettime","g":"change","word":"Moman trankil","text":"Yon peryòd, tankou pandan yon difizyon an dirèk, yon demo oswa pandan nwit lan, kote anyen pa ale an liy. Ekip yo kontinye travay ak teste, men ale an liy tann jiskaske l fini. Lòt kote yo rele l change freeze.","also":["moman trankil yo","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Yon fason pou travay kote moun ki bati lojisyèl la ak moun ki fè l mache travay kòm yon sèl ekip, ak anpil otomatizasyon, pou chanjman yo mete an liy souvan epi san danje."},{"id":"cicd","g":"change","word":"CI/CD (entegrasyon ak livrezon kontinyèl)","text":"Chanjman tout moun yo rantre nan vèsyon prensipal la souvan epi verifye otomatikman chak fwa (continuous integration), konsa lojisyèl la toujou pare pou mete an liy ak yon sèl peze bouton (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Deplwaman kontinyèl (continuous deployment)","text":"Yon etap pi lwen pase continuous delivery: chak chanjman ki pase verifikasyon yo ale an liy poukont li, san bouton pou peze.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (chèn travay)","text":"Seri etap otomatik yon chanjman pase sou wout li pou ale an liy, tankou build, tès, answit deplwaman.","also":["pipelines"]},{"id":"environment","g":"change","word":"Anviwònman (environment)","text":"Yon kopi separe sistèm lan pou yon sèl rezon, tankou youn pou bati ladan l, youn pou teste ladan l ak sa k an liy lan.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Anviwònman devlopman (development environment)","text":"Kopi devlopè a travay ladan l, souvan sou pwòp òdinatè l, kote kraze bagay pa fè pèsonn mal.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Anviwònman tès (test environment)","text":"Yon kopi separe sistèm lan yo itilize sèlman pou tès, pou yo pa manyen vrè sèvis la.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging (anviwònman final)","text":"Yon dènye kopi ki mete menm jan ak sa k an liy lan, pou yon dènye verifikasyon anvan yon chanjman ale an liy.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact (rezilta konstriksyon)","text":"Fichye oswa pakèt yon build pwodui, pare pou estoke, verifye oswa mete an liy.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix (reparasyon ijan)","text":"Yon reparasyon ijan yo mete an liy vit, andeyò plan nòmal la, paske yon bagay enpòtan kase.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch (ranje)","text":"Yon ti mizajou ki korije yon bug oswa ki fèmen yon twou sekirite. Aplike patch sekirite yo vit enpòtan anpil.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Nimewo vèsyon (version number)","text":"Yon etikèt tankou 2.4.1 ki di ki vèsyon ou genyen. Souvan premye nimewo a chanje pou gwo chanjman epi dènye a pou ti reparasyon.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Nòt vèsyon (release notes)","text":"Yon kout lis senp sou sa ki chanje nan yon vèsyon, pou moun k ap sèvi ak li, ansanm ak reparasyon yo ak limit yo konnen. Yo rele l changelog tou.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag (entèriptè fonksyonalite)","text":"Yon entèriptè limen/etenn pou yon fonksyonalite, pou nouvo travay ka ale an liy kache epi limen (oswa etenn ankò) san yon nouvo vèsyon.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward (korije pa devan)","text":"Korije yon move vèsyon lè w pibliye vit yon nouvo vèsyon korije olye w retounen nan ansyen an.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release (vèsyon kanari)","text":"Mete yon chanjman an liy pou yon ti gwoup an premye, epi pou tout moun sèlman lè l sanble bon. Non an soti nan kanari minè yo te konn pote anba tè pou avèti yo bonè.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Deplwaman ble-vèt (blue-green deployment)","text":"Kenbe de kopi sistèm an liy lan epi pase moun yo sou nouvo a yon sèl kou, pou ou ka tounen touswit si l pa mache.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Deplwaman san koupe (zero-downtime deployment)","text":"Mete yon nouvo vèsyon an liy san sèvis la janm kanpe pou itilizatè li yo.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Jesyon chanjman (change enablement)","text":"Ede chanjman yo reyisi: peze risk la, jwenn bon apwobasyon an epi chwazi yon bon moman. Yo rele l change management tou.","also":["change management"]},{"id":"cab","g":"change","word":"Komite konsiltatif chanjman (CAB)","text":"Yon gwoup ki gade chanjman enpòtan epi ki dakò si epi ki lè yo ka fèt.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Chanjman estanda (standard change)","text":"Yon chanjman ki gen ti risk, ki fèt chak fwa menm jan, yon fason ki deja fè prèv li, kidonk yo apwouve l davans.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Chanjman nòmal (normal change)","text":"Yon chanjman yo dwe verifye epi apwouve anvan yo fè l.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Chanjman ijans (emergency change)","text":"Yon chanjman ki dwe fèt touswit pou korije oswa anpeche gwo pwoblèm, ak yon apwobasyon pi rapid pou ale ak li.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Otomatizasyon (automation)","text":"Fè òdinatè a fè yon djòb repete poukont li, pou l pi rapid epi fèt menm jan chak fwa.","also":["automated","otomatik"],"noTip":1},{"id":"infra","g":"change","word":"Enfrastrikti (infrastructure)","text":"Machin yo, rezo yo ak sèvis yo lojisyèl la mache sou yo.","also":["infra"]},{"id":"iac","g":"change","word":"Enfrastrikti kòm kòd (IaC)","text":"Dekri sèvè ak paramèt ou yo nan fichye yo kenbe ak kòd la, pou yo ka rebati egzakteman menm jan chak fwa.","also":["IaC"]},{"id":"cloud","g":"change","word":"Nyaj (cloud)","text":"Lwe òdinatè, estokaj ak sèvis nan men yon gwo founisè atravè entènèt, olye w posede machin yo ou menm.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Founisè nyaj (cloud provider)","text":"Yon konpayi ki lwe pouvwa òdinatè sou entènèt, tankou Amazon Web Services (AWS), Microsoft Azure oswa Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting (ebèjman)","text":"Kote aplikasyon w oswa sit wèb ou rete epi mache pou moun ka rive jwenn li, anjeneral yo lwe l nan men yon konpayi."},{"id":"domain","g":"change","word":"Non domèn (domain name)","text":"Adrès wèb moun tape, tankou example.com. Ou lwe l pa ane, kidonk ou dwe renouvle l.","also":["domain names","domain","adrès wèb"]},{"id":"dns","g":"change","word":"DNS","text":"Kout pou domain name system: kanè adrès entènèt la, ki transfòme yon non tankou example.com an adrès bon òdinatè a.","also":["domain name system"]},{"id":"container","g":"change","word":"Kontenè (container)","text":"Yon pakèt sele ki gen yon aplikasyon ak tout sa li bezwen, pou l mache menm jan sou nenpòt òdinatè. Docker se zouti ki pi konnen.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Machin vityèl (VM)","text":"Yon fo òdinatè k ap mache andedan yon vrè, pou yon sèl gwo machin ka aji tankou anpil.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (san sèvè pou jere)","text":"Egzekite kòd san w pa okipe okenn sèvè ou menm: founisè a fè l mache lè sa nesesè epi ou peye sa w itilize."},{"id":"lb","g":"change","word":"Load balancer (distribitè chaj)","text":"Yon bagay ki separe vizitè yo sou plizyè sèvè, pou okenn sèl pa vin akable.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache (kachèt)","text":"Yon depo pratik pou dènye rezilta yo, kenbe tou pre, pou menm bagay la pa bezwen chèche oswa kalkile ankò. Vide l ka korije paj ki pa sanble ajou.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Rezo difizyon kontni (CDN)","text":"Yon gwoup sèvè atravè mond lan ki kenbe kopi paj ak imaj ou yo tou pre vizitè ou yo, pou yo chaje vit.","also":["CDN"]},{"id":"migration","g":"change","word":"Migrasyon (migration)","text":"Deplase done oswa sistèm soti nan yon ansyen konfigirasyon pou yon nouvo, oswa chanje ak prekosyon fason yon baz done òganize.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Sèvis","text":"Yon bagay ou bati moun konte sou li, tankou yon sit entènèt oswa yon app, ke yo okipe pou l kontinye mache. Tcheke “Pwojè sa a se yon sèvis” epi di sa li ofri, ki moun ki sèvi ak li ak ki moun ki sou gad.","also":["sèvis yo","service"]},{"id":"uptimepct","g":"run","word":"Tan disponib (uptime)","text":"Ki pati nan tan yon sèvis ap mache, anjeneral an pousantaj. 99,9% toujou pèmèt apeprè 43 minit kanpe chak mwa.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Verifikasyon uptime","text":"Yon verifikasyon otomatik, chak kèk minit, pou wè si sèvis ou a toujou reponn. Si li echwe plizyè fwa youn dèyè lòt, AI-gile ouvè yon kat ensidan pou kont li.","also":["uptime checks","verifikasyon disponibilite"]},{"id":"statuspage","g":"run","word":"Paj estati","text":"Yon paj piblik ki montre si yon sèvis ap mache (vèt, oranj oswa wouj) ak dènye nouvèl la, pou moun k ap sèvi ak li ka gade olye yo mande.","also":["paj estati yo","status page"]},{"id":"desk","g":"run","word":"Biwo sèvis","text":"Kote kesyon ak rapò moun ki itilize sèvis ou a rive. AI-gile klase chak youn kòm demann, ensidan oswa lide, epi li di ou lè li sanble ak yon bagay yo te deja rapòte.","also":["biwo sèvis yo","biwo èd","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Demann sèvis","text":"Yon moun k ap mande yon bagay nòmal, tankou yon nouvo kont oswa yon ti èd, olye l rapòte gen yon bagay ki kraze. Li tann tou pa l; yon ensidan pase anvan.","also":["demann sèvis yo"]},{"id":"incident","g":"run","word":"Ensidan","text":"Yon bagay ki kase oswa ki pa mache byen pou moun k ap sèvi ak li kounye a, tankou sit wèb la kanpe oswa trè dousman. Yon kat ensidan 🔥 pase devan fil la: remete l ap mache vin an premye.","also":["ensidan yo","incident"]},{"id":"major","g":"run","word":"Gwo ensidan","text":"Yon ensidan ki grav anpil: anpil moun touche, oswa lajan oswa done an danje. Yon sèl bouton mete tout ekip yo sou li (swarm), reveye moun ki sou gad la epi mande yon nouvèl estati chak 30 minit.","also":["gwo ensidan yo","major incident"]},{"id":"oncall","g":"run","word":"Sou gad","text":"Se ou ki reponn lè yon bagay kase, menm lannwit. Chak sèvis gen yon manm ekip sou gad yo reveye an premye pou ensidan li yo.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Delè pou reponn","text":"Konbyen tan yon kat ka tann yon premye repons, pa egzanp inèdtan pou yon ensidan. Apre sa li jwenn yon revèy wouj, pou anyen pa bliye an silans. Yo rele l objektif repons tou.","also":["objektif repons","response target"]},{"id":"postmortem","g":"run","word":"Post-mòtèm","text":"Yon ti gade dèyè apre yon ensidan: sa ki te pase, sa ki te ede ak sa pou chanje, san blame pèsonn. Yon ensidan pa ka fèmen san li.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Pwoblèm","text":"Kòz kache dèyè youn oswa plizyè ensidan. Yon kat 🧩 pwoblèm rasanble ensidan ki toujou ap tounen, pou yo jwenn kòz la epi ranje l pou tout tan.","also":["pwoblèm yo","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Kòz rasin","text":"Vrè rezon yon bagay kase, pa sèlman sa ou te wè k ap mal mache. Ranje kòz rasin lan epi ensidan an sispann tounen.","also":["root cause"]},{"id":"workaround","g":"run","word":"Solisyon tanporè","text":"Yon fason pou kenbe bagay yo ap mache jiskaske vrè reparasyon an pare, tankou rekòmanse yon bagay lè li bloke. Yo ekri l sou kat pwoblèm lan pou pèsonn pa oblije chèche l ankò.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Erè ki konnen","text":"Yon pwoblèm yo konprann kòz li men yo poko korije, anjeneral ak yon solisyon tanporè ki ekri. 🧩 Erè ki konnen fè lis yo, pou tout moun sèvi ak solisyon tanporè a olye yo fouye ankò.","also":["erè yo konnen","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Enstriksyon etap pa etap pou ranje yon kalite pwoblèm yo konnen, pou yo fè l menm jan, vit, chak fwa. Apre yon gwo ensidan ekip la ka pwopoze ou youn pou ou bay OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Eleman konfigirasyon","text":"Yon bagay sèvis ou a depann de li, tankou yon sèvè, yon domèn, yon sètifika, yon kle oswa yon founisè. 🗂️ Eleman konfigirasyon fè lis yo pou chak sèvis, pou ou ka wè sa yon ensidan afekte ak sa ki bezwen renouvle oswa sovgade.","also":["eleman konfigirasyon yo","configuration item"]},{"id":"expiry","g":"run","word":"Dat ekspirasyon","text":"Dat yon bagay sispann mache si yo pa renouvle l, tankou sètifika sekirite yon sit wèb oswa adrès wèb li. AI-gile siveye dat sa yo epi li fè yon kat pou renouvle chak 30 jou davans, pou anyen pa kanpe pa sipriz.","also":["dat ekspirasyon yo","ekspirasyon","siveyans ekspirasyon"]},{"id":"backup","g":"run","word":"Sovgad","text":"Yon kopi done ou te sere pi bonè, pou ou ka retounen sou li si yon bagay pèdi oswa abime. AI-gile fè yon sovgad tablo ou yo chak jou.","also":["sovgad yo","backup","backups"]},{"id":"restore","g":"run","word":"Retabli","text":"Remete done apati yon sovgad. Yon sovgad konte vrèman sèlman lè ou konnen li ka retabli, kidonk li vo lapenn eseye sa de tanzantan.","also":["retabli l","restore"]},{"id":"svcreview","g":"run","word":"Revizyon sèvis","text":"Yon gade dèyè sou yon mwa nan yon sèvis: ensidan ki louvri ak ki ranje, ki jan moun yo te jwenn repons vit, uptime ak tokèn ki sèvi. Revizyon chak mwa a montre sa pou chak sèvis.","also":["revizyon sèvis yo","revizyon chak mwa","revizyon mansyèl"]},{"id":"accessreview","g":"run","word":"Revizyon aksè","text":"Verifye chak 90 jou ki moun ki ka toujou antre: lyen pataj, wòl zanmi yo, ak modpas ak kle ki sove. Ou kenbe oswa retire chak youn, pou ansyen aksè pa rete trennen.","also":["revizyon aksè yo"]},{"id":"improvements","g":"run","word":"Lis amelyorasyon","text":"Tout sa ekip la deside amelyore, nan yon sèl kote: sijesyon retro, aksyon revizyon ak reparasyon pwoblèm, chak ak estati li. Ou jwenn li anba 📈 Amelyorasyon.","also":["lis amelyorasyon yo","amelyorasyon"]},{"id":"tokencap","g":"run","word":"Limit tokèn","text":"Yon limit chak mwa sou tokèn ajan yon sèvis ka itilize. A 80% ou resevwa yon avètisman; a 100% travay yo fè an aryèplan tann mwa pwochen oswa jiskaske ou monte limit lan.","also":["limit tokèn yo","token cap"]},{"id":"svcmgmt","g":"run","word":"Jesyon sèvis (service management)","text":"Tout sa ki enplike pou kenbe yon sèvis itil epi k ap mache pou moun ki konte sou li, jou apre jou."},{"id":"itil","g":"run","word":"ITIL","text":"Yon gid yo itilize anpil pou bon jesyon sèvis, ki kouvri bagay tankou ensidan, pwoblèm ak chanjman. Non an te vle di IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Jesyon sèvis IT (ITSM)","text":"Fè teknoloji mache kòm yon sèvis pou moun, ak fason klè pou jere demann, ensidan, chanjman ak amelyorasyon.","also":["ITSM"]},{"id":"managed","g":"run","word":"Sèvis jere (managed service)","text":"Yon sèvis yon lòt moun fè mache epi pran swen pou ou, anba yon akò sou ki jan li dwe mache byen.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Pwopriyetè sèvis (service owner)","text":"Moun ki reponn pou yon sèvis antye: ki jan li mache byen, konbyen li koute ak ki jan li amelyore.","also":["service owners"]},{"id":"sla","g":"run","word":"Akò nivo sèvis (SLA)","text":"Yon pwomès ekri bay kliyan sou ki jan yon sèvis pral mache byen, tankou “an liy 99,9% nan tan” oswa “reponn nan inèdtan”, souvan ak lajan retounen si l kase.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Objektif nivo sèvis (SLO)","text":"Pwòp sib ekip la pou ki jan yon sèvis dwe mache pandan yon peryòd, anjeneral fikse yon ti jan pi strik pase SLA a pou plis sekirite.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Endikatè nivo sèvis (SLI)","text":"Mezi reyèl ou verifye kont yon sib, tankou pousantaj vizit ki te chaje byen.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Disponibilite (availability)","text":"Si moun ka sèvi ak yon sèvis lè yo bezwen l, souvan mezire kòm uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Tan kanpe (downtime)","text":"Tan yon sèvis pa mache oswa li etenn, planifye oswa non.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Bidjè erè (error budget)","text":"Ti kantite echèk sib fyabilite w la pèmèt. Toutotan gen kèk ki rete, ou ka pran risk ak chanjman; yon fwa yo fini, ou ralanti.","also":["error budgets"]},{"id":"outage","g":"run","word":"Pàn (outage)","text":"Yon moman kote yon sèvis kanpe oswa kase grav pou itilizatè li yo.","also":["outages"]},{"id":"degraded","g":"run","word":"Degrade (degraded)","text":"Li mache, men mal: dousman, oswa kèk pati pa mache.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Siveyans (monitoring)","text":"Siveye yon sèvis otomatikman tout tan, pou pwoblèm yo repere, de preferans anvan itilizatè yo wè yo."},{"id":"observability","g":"run","word":"Obsèvabilite (observability)","text":"Ki jan ou ka di sa k ap pase andedan yon sistèm apati deyò, ak logs, nimewo ak traces li.","also":["o11y"]},{"id":"log","g":"run","word":"Log (jounal)","text":"Yon jounal yon pwogram kenbe sou sa l ap fè, ki sèvi pou konprann sa ki te mal.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace (tras)","text":"Yon dosye sou ki jan yon demann vwayaje atravè diferan pati yon sistèm, etap pa etap, ki montre kote l te ralanti.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latans (latency)","text":"Konbyen tan yon bagay pran pou reponn, tankou tan ki genyen ant lè w klike ak lè paj la parèt."},{"id":"alert","g":"run","word":"Alèt (alert)","text":"Yon mesaj otomatik ki di yon bagay bezwen atansyon, tankou sit wèb la pa reponn.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Fatig alèt (alert fatigue)","text":"Lè gen tèlman anpil alèt ke moun kòmanse inyore yo, menm sa ki enpòtan yo.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Tablo de bò (dashboard)","text":"Yon ekran ki montre nimewo ak estati ki pi enpòtan yo nan yon kou je.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging (rele an ijans)","text":"Rele oswa reveye an ijans moun ki sou gad la pou yon pwoblèm.","also":["paged"]},{"id":"escalation","g":"run","word":"Eskalad (escalation)","text":"Mete yon moun ki gen plis konpetans oswa otorite lè yon pwoblèm pa ka rezoud nan nivo aktyèl la, oswa pa ase vit.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triyaj (triage)","text":"Klase vit pwoblèm k ap antre selon ijans ak enpòtans yo, pou yo okipe sa ki pi grav yo an premye.","also":["triaged"]},{"id":"impact","g":"run","word":"Enpak (impact)","text":"Konbyen yon bagay afekte moun: konbyen, ak ki jan grav.","noTip":1},{"id":"urgency","g":"run","word":"Ijans (urgency)","text":"Ki vitès yo bezwen okipe yon bagay. Enpak ak ijans ansanm fikse priyorite a.","noTip":1},{"id":"plevels","g":"run","word":"Nivo priyorite (P1, P2…)","text":"Etikèt pou ijans yon pwoblèm. P1 se pi grav la epi mande aksyon touswit.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Fil tikè (ticket queue)","text":"Lis demann ak ensidan k ap tann pou yo pran.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"Premye liy ak dezyèm liy","text":"Nivo sipò: premye liy lan pran apèl la epi korije bagay senp; dezyèm liy lan gen konpetans pi pwofon pou sa ki pi difisil. Yo rele yo tier 1 ak tier 2 tou.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Chèf ensidan (incident commander)","text":"Yon sèl moun ki dirije repons ak yon ensidan, pou tout moun konnen ki moun ki deside ak ki moun ki fè kisa.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Tan repons (response time)","text":"Konbyen tan sa pran anvan yon moun pran yon demann oswa yon ensidan pou premye fwa.","also":["response times"]},{"id":"resolution","g":"run","word":"Tan rezolisyon (resolution time)","text":"Konbyen tan sa pran pou rezoud yon demann oswa yon ensidan nèt, depi rapò a jiska lè li korije.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Tan mwayen pou rekipere (MTTR)","text":"An mwayèn, konbyen tan sa pran pou remete yon sèvis ap mache apre li kase. MTTR ka vle di bagay ki yon ti jan diferan, kidonk di sa w ap mezire a.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Tan mwayen ant pàn (MTBF)","text":"An mwayèn, konbyen tan yon sèvis mache anvan yon bagay kase.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Baz done jesyon konfigirasyon (CMDB)","text":"Lis tout eleman konfigirasyon ou yo ak ki jan yo konekte, pou ou ka wè kisa ki depann de kisa.","also":["CMDB"]},{"id":"asset","g":"run","word":"Byen (asset)","text":"Nenpòt bagay ki gen valè ou posede oswa peye pou fè sèvis la mache, tankou yon laptòp, yon lisans lojisyèl oswa yon non domèn.","also":["assets","byen yo"],"noTip":1},{"id":"capplan","g":"run","word":"Planifikasyon kapasite (capacity planning)","text":"Asire w gen ase pouvwa òdinatè, estokaj ak moun pou sa k ap vini.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling (ogmante kapasite)","text":"Jere plis itilizatè lè w bay yon machin plis pouvwa (scaling up) oswa lè w ajoute plis machin (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Kontinuite biznis (business continuity)","text":"Plan pou kenbe bagay enpòtan yo ap mache lè yon gwo bagay mal pase, tankou pèdi yon biwo, yon founisè kle oswa òdinatè yo.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Rekiperasyon apre dezas (disaster recovery, DR)","text":"Plan ak zouti pou remete yon sèvis apre yon bagay grav, tankou pèdi yon sant done antye.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Objektif tan rekiperasyon (RTO)","text":"Pi lontan yon sèvis ka rete kanpe apre yon dezas anvan li dwe ap mache ankò.","also":["RTO"]},{"id":"rpo","g":"run","word":"Objektif pwen rekiperasyon (RPO)","text":"Konbyen done resan ou ka aksepte pèdi, mezire an tan. Yon RPO inèdtan vle di sovgad omwen chak inèdtan.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redondans (redundancy)","text":"Gen pyès rechany ki pare, tankou yon dezyèm sèvè, pou yon sèl echèk pa kanpe sèvis la."},{"id":"failover","g":"run","word":"Failover (baskile sou rechany)","text":"Pase otomatikman sou yon sistèm rechany lè sa nòmal la echwe.","also":["fail over"]},{"id":"spof","g":"run","word":"Sèl pwen echèk (single point of failure)","text":"Yon sèl pati ki rale tout bagay ak li lè l kase, paske pa gen rechany.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Fenèt antretyen (maintenance window)","text":"Yon moman planifye kote yon sèvis ka sispann oswa ralanti pou antretyen, anonse itilizatè yo davans.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Transmisyon travay (handover)","text":"Pase travay, konesans ak responsablite bay yon lòt moun oswa ekip, pou anyen pa pèdi.","also":["handovers"]},{"id":"kb","g":"run","word":"Baz konesans (knowledge base)","text":"Yon koleksyon atik èd ak repons, pou itilizatè yo ak pou ekip la.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Satisfaksyon kliyan (CSAT)","text":"Yon nòt nan men itilizatè ki di jan yo te kontan, souvan mande apre yo fin fèmen yon demann.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Founisè (supplier)","text":"Yon konpayi deyò ou konte sou li, tankou founisè hosting ou. Yo rele l vendor oswa third party tou.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Retrèt sèvis (service retirement)","text":"Etenn yon sèvis pou toutan, san danje: avèti itilizatè li yo, okipe done ak aksè li yo, epi sispann depans li yo.","also":["retiring a service"]},{"id":"eol","g":"run","word":"Fen vi (end of life, EOL)","text":"Lè yon pwodwi sispann resevwa mizajou oswa sipò nan men moun ki fè l, kidonk yo dwe ranplase l.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Sekirite entènèt (cybersecurity)","text":"Pwoteje sistèm ak done pou pèsonn pa kase antre ladan yo, vòlè yo oswa domaje yo.","also":["cyber security","sibè sekirite"]},{"id":"authn","g":"sec","word":"Otantifikasyon (authentication)","text":"Verifye ki moun yon moun ye, anjeneral ak yon modpas oswa yon kòd. Souvan yo abreje l an authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Otorizasyon (authorisation)","text":"Verifye sa yon moun gen dwa fè yon fwa ou konnen ki moun li ye. Souvan yo abreje l an authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Otantifikasyon miltifaktè (MFA)","text":"Konekte ak de prèv oswa plis, tankou yon modpas plis yon kòd sou telefòn ou. Yo rele l two-factor (2FA) tou.","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Koneksyon yon sèl fwa (single sign-on, SSO)","text":"Konekte yon sèl fwa pou antre nan anpil sistèm, tankou sèvi ak kont travay ou toupatou.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Jestyonè modpas (password manager)","text":"Yon aplikasyon ki kreye modpas fò epi ki sonje yo pou ou.","also":["password managers"]},{"id":"secret","g":"sec","word":"Sekrè (secret)","text":"Yon modpas, yon kle oswa yon lòt kòd prive yon pwogram itilize pou antre nan yon bagay. Pa janm dwe pataje l oswa ekri l nan kòd la.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Kle API (API key)","text":"Yon kòd sekrè ki pèmèt yon pwogram itilize API yon lòt sèvis, epi ki montre ki moun k ap itilize l (epi k ap peye pou li).","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Token aksè (access token)","text":"Yon pas tanporè ki pwouve yon pwogram gen dwa antre, kidonk li pa bezwen modpas ou chak fwa. Pa menm bagay ak yon token AI.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Chifreman (encryption)","text":"Brouye enfòmasyon pou se sèlman yon moun ki gen bon kle a ki ka li l.","also":["encrypted","encrypt","chifre"]},{"id":"https","g":"sec","word":"HTTPS","text":"Fason ki an sekirite paj wèb yo vwayaje, kadna nan navigatè w la montre l, pou pèsonn nan mitan pa ka li yo oswa chanje yo."},{"id":"cert","g":"sec","word":"Sètifika SSL/TLS (certificate)","text":"Yon kat idantite dijital ki pèmèt yon sit wèb pwouve ki moun li ye epi sèvi ak HTTPS. Li ekspire, kidonk ou dwe renouvle l.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Pèmisyon (permissions)","text":"Règ sou ki moun ki gen dwa wè oswa chanje kisa.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Dwa minimòm (least privilege)","text":"Bay chak moun oswa pwogram sèlman aksè yo vrèman bezwen, pou sèlman tan yo bezwen l.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Kontwòl aksè selon wòl (RBAC)","text":"Bay aksè selon wòl, tankou lektè oswa editè, olye moun pa moun.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vilnerabilite (vulnerability)","text":"Yon feblès yon moun ta ka sèvi ak li pou kase antre oswa fè dega.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day (feblès san rimèd)","text":"Yon feblès atakan yo konnen anvan moun ki fè lojisyèl la gen tan korije l.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware (lojisyèl malveyan)","text":"Lojisyèl danjere, tankou viris, fèt pou domaje, espyone oswa vòlè."},{"id":"ransomware","g":"sec","word":"Ransomware (lojisyèl ranson)","text":"Lojisyèl malveyan ki bloke fichye w yo epi mande lajan pou debloke yo. Bon sovgad se pi bon defans.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing (fo mesaj pyèj)","text":"Fo mesaj ki eseye twonpe w pou w bay modpas oswa lajan, oswa pou w louvri yon bagay danjere.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Jeni sosyal (social engineering)","text":"Twonpe moun, olye òdinatè, pou yo bay aksè, tankou yon fo apèl “sipò IT”."},{"id":"firewall","g":"sec","word":"Firewall (miray dife)","text":"Yon gadyen ki deside ki trafik rezo ki ka antre oswa soti.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Kout pou virtual private network: yon lyen prive, chifre sou entènèt, souvan itilize pou rive nan sistèm travay yo an sekirite.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Deni sèvis (DoS, DDoS)","text":"Inonde yon sèvis ak tèlman anpil fo trafik ke vrè moun pa ka sèvi ak li. DDoS vle di sa soti nan anpil òdinatè alafwa.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Pen test (tès penetrasyon)","text":"Anboche ekspè ki la pou ede w pou yo eseye kase antre, pou jwenn feblès yo anvan vrè atakan yo jwenn yo.","also":["pen test","pen testing","penetration testing","pentest","penetration test"]},{"id":"audit","g":"sec","word":"Odit sekirite (security audit)","text":"Yon verifikasyon serye sou ki jan yon bagay byen pwoteje, selon yon lis bon pratik.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Modelizasyon menas (threat modelling)","text":"Reflechi sou ki moun ki ta ka atake yon bagay, ki jan, ak sa w ta fè pou sispann yo.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Fwit done (data breach)","text":"Lè enfòmasyon prive soti rive nan men moun ki pa ta dwe genyen yo, oswa pèdi oswa chanje san pèmisyon.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Done pèsonèl (personal data)","text":"Nenpòt enfòmasyon sou yon moun yo ka idantifye, tankou yon non, yon adrès imèl oswa yon kote. Yo rele l PII tou.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Lwa Ewopeyen sou done pèsonèl (Wayòm Ini gen pwòp vèsyon pa l): kolekte sèlman sa ou bezwen, kenbe l an sekirite, epi kite moun wè oswa efase pa yo.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Pwoteksyon done (data protection)","text":"Pran swen done pèsonèl yo kòrèkteman epi nan respè lalwa.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Politik konfidansyalite (privacy policy)","text":"Yon paj piblik ki di ki done pèsonèl ou kolekte, poukisa, epi sa w fè avèk yo.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Konsantman (consent)","text":"Yon wi klè, lib yon moun pou done l yo itilize yon fason presi. Li ka retire l nenpòt ki lè.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie (koki)","text":"Yon ti fichye yon sit wèb sove nan navigatè w pou sonje bagay, tankou lefèt ou konekte. Gen kèk ki mande konsantman w an premye.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimizasyon done (data minimisation)","text":"Kolekte epi kenbe sèlman done pèsonèl ou vrèman bezwen pou djòb la.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Konsèvasyon done (data retention)","text":"Konbyen tan yo kenbe done anvan yo efase yo. Pa kenbe yo plis pase sa ki nesesè pi an sekirite epi souvan se lalwa.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonimizasyon (anonymisation)","text":"Chanje done yo pou pèsonn pa ka idantifye okenn moun apati yo ankò, yon fason rezonab.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Psedonimizasyon (pseudonymisation)","text":"Ranplase non ak lòt detay ak kòd, ak yon kle kenbe apa pou lye yo ankò. Se toujou done pèsonèl.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Akò tretman done (DPA)","text":"Yon kontra ki di ki jan yon founisè ka okipe done pèsonèl nan non ou.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Evalyasyon enpak sou pwoteksyon done (DPIA)","text":"Yon gade ak prekosyon, anvan w kòmanse, sou ki jan yon plan pou itilize done pèsonèl ka afekte moun ak ki jan pou diminye risk yo.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Jounal odit (audit log)","text":"Yon dosye sou ki moun ki fè kisa epi ki lè, pou aksyon yo ka verifye apre.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Konfòmite (compliance)","text":"Swiv lwa, règ ak nòm ki aplike pou ou, epi kapab montre ou fè sa.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Yon nòm entènasyonal byen konnen pou jere sekirite enfòmasyon. Konpayi yo ka sètifye selon li.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Yon rapò ameriken, oditè deyò verifye, ki montre yon konpayi pran swen done kliyan yo kòrèkteman.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Ajan","text":"Yon AI ki travay sou yon tach poukont li: li li kòd la, fè chanjman, egzekite verifikasyon epi rapòte. Travay li toujou verifye.","also":["agent","agents","ajan"]},{"id":"token","g":"ai","word":"Token","text":"Ti moso tèks yon AI li epi ekri, apeprè twa ka yon mo chak. Yo konte itilizasyon AI an tokens, kidonk mwens tokens kite plis nan plan ou.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Yon ti kòmand ki egzekite poukont li nan yon moman fiks, pa egzanp lè yon sesyon AI kòmanse, pou ekip la tande kòmantè ou yo.","also":["hooks"]},{"id":"ai","g":"ai","word":"Entèlijans atifisyèl (AI)","text":"Sistèm òdinatè ki fè bagay nou jeneralman panse mande yon moun, tankou ekri, reponn kesyon oswa rekonèt imaj.","also":["AI","artificial intelligence","IA"],"noTip":1},{"id":"ml","g":"ai","word":"Aprantisaj machin (machine learning, ML)","text":"Yon fason pou fè òdinatè aprann modèl nan anpil egzanp, olye yo ba yo règ egzak.","also":["machine learning"]},{"id":"model","g":"ai","word":"Modèl (model)","text":"“Sèvo” yon sistèm AI ki antrene, bati lè li aprann nan yon gwo kantite egzanp. Modèl yo diferan nan konpetans, vitès ak pri.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Gwo modèl lang (LLM)","text":"Yon modèl AI ki antrene sou yon gwo kantite tèks, pou l ka li epi ekri lang.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"AI jeneratif (generative AI)","text":"AI ki kreye nouvo bagay, tankou tèks, imaj oswa kòd, olye li sèlman klase oswa repere yo.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Yon pwogram ou pale avèk li nan lang chak jou, lè w tape oswa lè w pale.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt (demann bay AI)","text":"Sa ou bay yon AI: kesyon w oswa enstriksyon w, ansanm ak sa ou ba li. Prompt ki pi klè anjeneral jwenn pi bon repons.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering (konsepsyon prompt)","text":"Konpetans pou ekri prompt ki bay rezilta fyab epi itil."},{"id":"sysprompt","g":"ai","word":"Prompt sistèm (system prompt)","text":"Enstriksyon an aryèplan yon AI resevwa anvan konvèsasyon an kòmanse, ki fikse wòl li ak règ li. Yo peze plis pase sa ou tape.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Kontèks (context)","text":"Tout sa AI a ka wè pandan l ap travay: enstriksyon yo, mesaj ou yo, fichye li te li ak repons anvan yo.","noTip":1},{"id":"ctxwin","g":"ai","word":"Fenèt kontèks (context window)","text":"Konbyen yon AI ka kenbe nan tèt li alafwa, mezire an tokens. Pi lwen pase sa, pati ki pi ansyen yo tonbe oswa rezime.","also":["context windows"]},{"id":"session","g":"ai","word":"Sesyon (session)","text":"Yon konvèsasyon travay ak yon AI, depi kòmansman jiska fen. Yon nouvo sesyon kòmanse ak yon memwa nèf.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memwa (memory)","text":"Nòt yon AI kenbe ant sesyon yo, pou l sonje preferans ou ak desizyon anvan yo.","noTip":1},{"id":"hallucination","g":"ai","word":"Alisinasyon (hallucination)","text":"Lè yon AI di yon bagay ak tout asirans, men se envante oswa se fo. Verifye fè ki enpòtan yo.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Antrennman (training)","text":"Montre yon modèl yon gwo kantite egzanp pou l aprann, anvan pèsonn sèvi ak li.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Done antrennman (training data)","text":"Egzanp yon modèl te aprann yo. Konesans li sispann nan dat yo te kolekte done sa yo.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Dat limit konesans (knowledge cutoff)","text":"Dat konesans entegre yon AI fini. Li pap konnen bagay ki vin apre sof si l chèche yo.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning (ajisteman fen)","text":"Plis antrennman yon modèl ki deja egziste sou pwòp egzanp ou yo, pou l vin pi bon nan yon djòb presi.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Enferans (inference)","text":"Yon modèl AI k ap itilize vre pou reponn yon bagay, kontrèman ak lè l ap antrene.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Itilizasyon zouti (tool use)","text":"Yon AI ki kapab fè bagay, pa sèlman pale: egzekite kòmand, li fichye oswa chèche sou entènèt, atravè zouti aplikasyon an ba li.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent (sou-ajan)","text":"Yon AI asistan ke yon AI prensipal bay yon ti travay pou fè, epi ki remèt li rezilta a.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Miltiajan (multi-agent)","text":"Plizyè AI k ap travay ansanm sou yon sèl moso travay, chak ak pati pa l, tankou yon ti ekip.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Otonomi (autonomy)","text":"Konbyen yon AI gen dwa fè poukont li anvan l dwe mande yon moun.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Yon moun nan sikui a (human in the loop)","text":"Kenbe yon moun enplike pou verifye oswa apwouve sa AI a fè nan pwen kle yo. Nan AI-gile, se ou menm.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Gadfou (guardrails)","text":"Limit ak verifikasyon ki kenbe aksyon yon AI an sekirite, tankou bezwen apwobasyon anvan anyen ale an liy. Yo diminye risk erè yo, men yo pa elimine yo.","also":["guardrail","gadfou"]},{"id":"rag","g":"ai","word":"Jenerasyon ogmante pa rechèch (RAG)","text":"Kite yon AI chèche bagay nan pwòp dokiman ou yo anvan l reponn, pou repons li yo baze sou fè ou yo.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (reprezantasyon nimerik)","text":"Transfòme yon tèks an yon lis nimewo ki kenbe sans li, pou yon òdinatè ka jwenn bagay ki gen sans menm jan.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Baz done vektè (vector database)","text":"Yon baz done ki fèt pou chèche nan lis nimewo sa yo (embeddings), pou jwenn materyèl ki gen yon sans menm jan.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Yon fason komen pou branche zouti ak sous done nan aplikasyon AI, pou yon AI ka sèvi ak yo.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Tanperati (temperature)","text":"Yon paramèt ki di jan repons yon AI ka avantire. Ba bay repons ki pi estab, ki pi previzib; wo bay repons ki pi varye. Ni youn ni lòt pa fè l toujou gen rezon.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Miltimodal (multimodal)","text":"Kapab travay ak plis pase yon kalite enfòmasyon, tankou tèks, imaj ak son.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evalyasyon (eval)","text":"Yon tès planifye sou ki jan yon AI fè sou egzanp chwazi, pou ou ka konpare modèl oswa prompt.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Patipri (bias)","text":"Lè yon AI (oswa yon moun) panche enjistman yon bò, souvan akòz sa li te aprann ladan l.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI responsab (responsible AI)","text":"Itilize AI yon fason jis, san danje epi onèt, ak moun ki toujou reponn pou rezilta yo.","also":["ethical AI","AI etik"]},{"id":"injection","g":"ai","word":"Prompt injection (ensèsyon prompt)","text":"Yon riz kote enstriksyon kache nan yon paj wèb oswa yon fichye eseye fè yon AI fè yon bagay itilizatè li pa t mande.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Limit vitès (rate limit)","text":"Yon plafon sou konbyen demann ou ka voye bay yon sèvis nan yon tan fiks. Si w depase l, ou oblije tann.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Limit itilizasyon (usage limit)","text":"Konbyen travay AI plan ou pèmèt nan yon peryòd, epi apre sa li sispann oswa li koute plis.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding (kòde sou santiman)","text":"Bati lojisyèl pi fò pa dekri sa w vle bay yon AI epi kite l ekri kòd la.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Bidjè (budget)","text":"Kantite lajan ou mete sou kote pou yon bagay.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Estimasyon pri (cost estimate)","text":"Yon kalkil apeprè sou konbyen yon bagay pral koute anvan w kòmanse.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Retou sou envestisman (ROI)","text":"Sa w jwenn an retou konpare ak sa w mete. Si l pozitif, li te vo lapenn.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Pri total posesyon (TCO)","text":"Tout sa yon bagay koute vre pandan tout vi li, pa sèlman pri pou achte l: fè l mache, sipò, amelyorasyon ak finalman retire l.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx ak OpEx","text":"CapEx se lajan ou depanse davans pou bagay ou kenbe; OpEx se depans ki kontinye, tankou fakti chak mwa.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abònman (subscription)","text":"Peye regilyèman, anjeneral chak mwa oswa chak ane, pou kontinye sèvi ak yon bagay.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Lojisyèl kòm sèvis (SaaS)","text":"Lojisyèl ou sèvi ak sou entènèt epi peye pa abònman, pandan moun ki fè l la fè l mache pou ou.","also":["SaaS"]},{"id":"payg","g":"money","word":"Peye selon itilizasyon (pay as you go)","text":"Peye sèlman pou sa w itilize, tankou kalkil nan nyaj oswa tokens AI.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Depasman (overage)","text":"Itilizasyon ki depase sa plan ou enkli, ki ka koute plis.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Alèt faktirasyon (billing alert)","text":"Yon mesaj lè depans oswa itilizasyon rive nan yon nivo ou chwazi. Li avèti w, men li pa toujou sispann lòt frè.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Nivo gratis (free tier)","text":"Yon nivo gratis yon sèvis peye, ak limit. Pratik pou kòmanse.","also":["free plan","plan gratis"]},{"id":"pricing","g":"money","word":"Plan tarif (pricing plan)","text":"Diferan pakèt yon sèvis vann, chak ak pwòp pri ak limit li.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Lisans (licence)","text":"Règ pou ki jan ou ka sèvi, kopye, chanje oswa pataje yon bagay yon lòt moun fè, tankou lojisyèl, polis oswa imaj.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Sous louvri (open source)","text":"Lojisyèl ki gen kòd tout moun ka li, itilize epi souvan chanje gratis, anba règ lisans li.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Lisans sous louvri (open source licence)","text":"Règ ki vini ak kòd sous louvri. Gen kèk ki kite w fè prèske tout bagay (tankou MIT); gen lòt ki mande w pataje chanjman ou yo tou (tankou GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Pwopriyetè (proprietary)","text":"Posede pa yon konpayi epi pa lib pou kopye oswa chanje. Kontrè sous louvri.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Dwa dotè (copyright)","text":"Dwa legal yon kreyatè genyen pou kontwole kopi travay li, ansanm ak kòd ak tèks.","also":["copyrighted","copyright"],"noTip":1},{"id":"ip","g":"money","word":"Pwopriyete entelektyèl (IP)","text":"Lide ak kreyasyon lalwa konsidere kòm posede, tankou kòd, konsepsyon, non ak logo.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Kondisyon sèvis (terms of service)","text":"Règ ou aksepte lè w sèvi ak yon sèvis.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Kontra (contract)","text":"Yon akò ekri ant de pati ke lalwa pral sipòte.","also":["contracts","kontra yo"],"noTip":1},{"id":"sow","g":"money","word":"Deskripsyon travay (statement of work, SOW)","text":"Yon dokiman ki presize egzakteman ki travay ki pral fèt, pou ki lè epi pou konbyen.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Pri fiks (fixed price)","text":"Yon pri yo dakò pou tout djòb la, kèlkeswa konbyen tan li pran.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Tan ak materyèl (time and materials)","text":"Peye pou lè yo travay vre ak bagay yo itilize vre, olye yon pri fiks.","also":["T&M"]},{"id":"invoice","g":"money","word":"Fakti (invoice)","text":"Yon bòdwo ki mande peman pou travay ki fèt oswa machandiz ki livre.","also":["invoices","fakti yo"],"noTip":1},{"id":"lockin","g":"money","word":"Prizonye founisè (vendor lock-in)","text":"Lè kite yon founisè tèlman difisil oswa chè ke ou kole avèk yo.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Apwovizyònman (procurement)","text":"Pwosesis chwazi ak achte nan men founisè yo.","also":["achte"]},{"id":"servicecredit","g":"money","word":"Kredi sèvis (service credit)","text":"Lajan retounen oswa yon rabè ou jwenn lè yon founisè pa respekte SLA li.","also":["service credits"]}]}};
